INSERT INTO public.questoes (id,rank,prioridade_base,prioridade_faixa,topic,origin,file_source,stem,options,answer,year,qnum,score,band,resolution,summary) VALUES ('1058717',2259,72,'P2','AFO, Direito Financeiro e Contabilidade Pública - Despesas de Exercícios Anteriores (DEA)','FAFIPA - Cont Jr (FC Foz)/FC Foz do Iguaçu/2019','Caderno Contabilidade Pública Parte 4','A ocorrência de despesas de exercícios anteriores caracteriza-se, entre outros fatores, como uma exceção ao princípio da competência para a contabilidade. No entanto, ante o caráter excepcional da mesma, o reconhecimento da despesa a ser paga a este título depende de alguns pressupostos. Neste sentido, acerca do instituto das despesas de exercícios anteriores e sua previsão na Lei nº 4.320/64, assinale a alternativa CORRETA:','[["A","É desembolsada em exercícios anteriores, mas gerada no exercício corrente."],["B","Não possuíam crédito em dotação própria com saldo suficiente para atendê-las no exercício em que deveriam ser geradas."],["C","Consiste na entrega de numerário a servidor, sempre precedida de empenho na dotação própria para o fim de realizar despesas, que não possam subordinar-se ao processo normal de aplicação."],["D","São notadamente despesas orçamentárias, apesar de não ter sido empenhadas em época própria."]]'::jsonb,'D',2019,684,NULL,NULL,'{"regra":"A resolução deve aplicar a regra orçamentária, financeira ou contábil pública pertinente ao tema, respeitando a classificação e o estágio indicados no enunciado.","passos":["Identifique o núcleo do tema: AFO, Direito Financeiro e Contabilidade Pública - Despesas de Exercícios Anteriores (DEA).","Aplique a regra ao caso concreto e elimine as alternativas incompatíveis com o conceito cobrado.","O gabarito registrado é D."],"calculo":"Quando houver valores no enunciado, a conta deve ser montada apenas com os dados fornecidos e conforme a relação conceitual indicada acima.","correta":"D — São notadamente despesas orçamentárias, apesar de não ter sido empenhadas em época própria.","erradas":["As demais alternativas contrariam a definição, classificação ou consequência contábil aplicável ao caso."],"fundamento":"AFO, Direito Financeiro e Contabilidade Pública - Despesas de Exercícios Anteriores (DEA)"}'::jsonb,'A ocorrência de despesas de exercícios anteriores caracteriza-se, entre outros fatores, como uma exceção ao princípio da competência para a contabilidade. No entanto, ante o caráter excepcional da mesma, o reconhecimento da despesa a ser paga a este título depende de alguns pressupostos. Neste sentido, acerca do instituto das despesas de exercícios anteriores e sua previsão na ') ON CONFLICT (id) DO UPDATE SET prioridade_base=EXCLUDED.prioridade_base, prioridade_faixa=EXCLUDED.prioridade_faixa, topic=EXCLUDED.topic, origin=EXCLUDED.origin, file_source=EXCLUDED.file_source, stem=EXCLUDED.stem, options=EXCLUDED.options, answer=EXCLUDED.answer, year=EXCLUDED.year, qnum=EXCLUDED.qnum, score=EXCLUDED.score, band=EXCLUDED.band, resolution=EXCLUDED.resolution, summary=EXCLUDED.summary;
INSERT INTO public.questoes (id,rank,prioridade_base,prioridade_faixa,topic,origin,file_source,stem,options,answer,year,qnum,score,band,resolution,summary) VALUES ('3935808',2260,76,'P2','AFO, Direito Financeiro e Contabilidade Pública - Gestão Patrimonial (arts. 43 a 47 da LRF)','FAFIPA - PSP (SESA PR)/SESA PR/Administrador/2026','Caderno Contabilidade Pública Parte 4','Com base na Seção II da Lei Complementar Federal nº 101/2000 (Lei de Responsabilidade Fiscal), que trata da preservação do patrimônio público, analise as regras relativas à aplicação de receitas de capital, à inclusão de despesas em projetos de lei orçamentária e aos requisitos para a validade de atos de desapropriação e assinale a alternativa CORRETA.','[["A","É nulo o ato de desapropriação de imóvel urbano expedido sem o prévio depósito judicial do valor da indenização."],["B","As despesas destinadas à conservação do patrimônio público podem ser incluídas em projetos não previstos no plano plurianual, independentemente de autorização legal."],["C","A lei orçamentária pode deixar de contemplar despesas de preservação do patrimônio público quando houver limitação de créditos adicionais."],["D","É permitida a utilização de receita de capital proveniente da alienação de bens públicos para o financiamento de despesas correntes, desde que autorizada por lei específica."],["E","O Poder Executivo está dispensado de encaminhar informações ao Legislativo sobre despesas de conservação do patrimônio público."]]'::jsonb,'A',2026,685,NULL,NULL,'{"regra":"A resolução deve aplicar a regra orçamentária, financeira ou contábil pública pertinente ao tema, respeitando a classificação e o estágio indicados no enunciado.","passos":["Identifique o núcleo do tema: AFO, Direito Financeiro e Contabilidade Pública - Gestão Patrimonial (arts. 43 a 47 da LRF).","Aplique a regra ao caso concreto e elimine as alternativas incompatíveis com o conceito cobrado.","O gabarito registrado é A."],"calculo":"Quando houver valores no enunciado, a conta deve ser montada apenas com os dados fornecidos e conforme a relação conceitual indicada acima.","correta":"A — É nulo o ato de desapropriação de imóvel urbano expedido sem o prévio depósito judicial do valor da indenização.","erradas":["As demais alternativas contrariam a definição, classificação ou consequência contábil aplicável ao caso."],"fundamento":"AFO, Direito Financeiro e Contabilidade Pública - Gestão Patrimonial (arts. 43 a 47 da LRF)"}'::jsonb,'Com base na Seção II da Lei Complementar Federal nº 101/2000 (Lei de Responsabilidade Fiscal), que trata da preservação do patrimônio público, analise as regras relativas à aplicação de receitas de capital, à inclusão de despesas em projetos de lei orçamentária e aos requisitos para a validade de atos de desapropriação e assinale a alternativa CORRETA.') ON CONFLICT (id) DO UPDATE SET prioridade_base=EXCLUDED.prioridade_base, prioridade_faixa=EXCLUDED.prioridade_faixa, topic=EXCLUDED.topic, origin=EXCLUDED.origin, file_source=EXCLUDED.file_source, stem=EXCLUDED.stem, options=EXCLUDED.options, answer=EXCLUDED.answer, year=EXCLUDED.year, qnum=EXCLUDED.qnum, score=EXCLUDED.score, band=EXCLUDED.band, resolution=EXCLUDED.resolution, summary=EXCLUDED.summary;
INSERT INTO public.questoes (id,rank,prioridade_base,prioridade_faixa,topic,origin,file_source,stem,options,answer,year,qnum,score,band,resolution,summary) VALUES ('3998111',2261,75,'P2','AFO, Direito Financeiro e Contabilidade Pública - Gestão Patrimonial (arts. 43 a 47 da LRF)','FAFIPA - Cont (Leópolis)/Pref Leópolis/2025','Caderno Contabilidade Pública Parte 4','O texto seguinte servirá de base para responder à questão. Em virtude da pandemia de Coronavírus, o Chefe do Poder Executivo de Terra Justa determinou a migração de todos os servidores do Departamento Administrativo para o regime de teletrabalho, tornando o prédio por eles ocupado inservível para a administração. Assim, o Prefeito solicitou à Câmara Municipal autorização para alienar o imóvel, a qual foi concedida por meio de Lei em 30 de novembro de 2024. Seis meses após a autorização, o leilão foi realizado, e o bem foi arrematado à vista por R$ 200.000,00. Na mesma data, o valor contábil líquido do ativo era de R$ 140.000,00. Com base na Lei Complementar nº 101/2000 – notoriamente conhecida como Lei de Responsabilidade Fiscal (LRF) – é CORRETO afirmar, sobre os recursos arrecadados com a alienação do imóvel, que:','[["A","os recursos deverão ser alocados exclusivamente na aquisição de novo bem imobilizado, com o objetivo de preservar e fortalecer o patrimônio público."],["B","é vedada a aplicação dos recursos para custeio de despesas correntes, exceto quando legalmente destinados ao financiamento dos regimes de previdência social, tanto o geral quanto o próprio dos servidores públicos."],["C","é permitida a utilização dos valores para o pagamento de vencimentos e demais componentes remuneratórios dos servidores ativos da Secretaria da Saúde."],["D","os recursos estão vinculados à aplicação exclusiva na manutenção e conservação do patrimônio público já existente."],["E","os valores poderão ser destinados a diversas finalidades, a critério discricionário do Chefe do Poder Executivo."]]'::jsonb,'B',2025,686,NULL,NULL,'{"regra":"A resolução deve aplicar a regra orçamentária, financeira ou contábil pública pertinente ao tema, respeitando a classificação e o estágio indicados no enunciado.","passos":["Identifique o núcleo do tema: AFO, Direito Financeiro e Contabilidade Pública - Gestão Patrimonial (arts. 43 a 47 da LRF).","Aplique a regra ao caso concreto e elimine as alternativas incompatíveis com o conceito cobrado.","O gabarito registrado é B."],"calculo":"Quando houver valores no enunciado, a conta deve ser montada apenas com os dados fornecidos e conforme a relação conceitual indicada acima.","correta":"B — é vedada a aplicação dos recursos para custeio de despesas correntes, exceto quando legalmente destinados ao financiamento dos regimes de previdência social, tanto o geral quanto o próprio dos servidores públicos.","erradas":["As demais alternativas contrariam a definição, classificação ou consequência contábil aplicável ao caso."],"fundamento":"AFO, Direito Financeiro e Contabilidade Pública - Gestão Patrimonial (arts. 43 a 47 da LRF)"}'::jsonb,'O texto seguinte servirá de base para responder à questão. Em virtude da pandemia de Coronavírus, o Chefe do Poder Executivo de Terra Justa determinou a migração de todos os servidores do Departamento Administrativo para o regime de teletrabalho, tornando o prédio por eles ocupado inservível para a administração. Assim, o Prefeito solicitou à Câmara Municipal autorização para a') ON CONFLICT (id) DO UPDATE SET prioridade_base=EXCLUDED.prioridade_base, prioridade_faixa=EXCLUDED.prioridade_faixa, topic=EXCLUDED.topic, origin=EXCLUDED.origin, file_source=EXCLUDED.file_source, stem=EXCLUDED.stem, options=EXCLUDED.options, answer=EXCLUDED.answer, year=EXCLUDED.year, qnum=EXCLUDED.qnum, score=EXCLUDED.score, band=EXCLUDED.band, resolution=EXCLUDED.resolution, summary=EXCLUDED.summary;
INSERT INTO public.questoes (id,rank,prioridade_base,prioridade_faixa,topic,origin,file_source,stem,options,answer,year,qnum,score,band,resolution,summary) VALUES ('3680361',2262,73,'P2','AFO, Direito Financeiro e Contabilidade Pública - Gestão Patrimonial (arts. 43 a 47 da LRF)','FAFIPA - Cont (CM SJ Pinhais)/CM SJ dos Pinhais/2023','Caderno Contabilidade Pública Parte 4','O texto seguinte servirá de base para responder a questão a seguir. Em face da pandemia de Coronavírus, o Chefe do Poder Executivo de Carcará decidiu realocar todos os servidores do Departamento de Recursos Humanos para o regime de teletrabalho, motivo pelo qual prédio que ocupavam tornou-se inservível para a administração. Diante disso, o Prefeito pediu autorização à Câmara Municipal para alienar o prédio, que foi concedida através de Lei em30/11/2021. Seis meses depois, o Leilão foi realizado, e o imóvel foi arrematado à vista por R$175.000,00. Na mesma data, o valor contábil líquido do ativo era de R$ 155.000,00. Sobre os recursos arrecadados no Leilão, e de acordo com a LRF - Lei Complementar nº 101/2000 -, é CORRETO afirmar que:','[["A","deverão ser aplicados exclusivamente na aquisição de outro ativo imobilizado, a fim de preservar patrimônio público."],["B","poderão ser utilizados para pagamento de remuneração dos servidores ativos da Secretaria deseducação."],["C","é vedada sua aplicação para o financiamento de despesa corrente, salvo se destinada por lei aos regimes de previdência social, geral e próprio dos servidores públicos."],["D","deverão ser aplicados exclusivamente na manutenção de bens públicos já existentes."],["E","poderão ser aplicados para qualquer finalidade, de acordo com a vontade do Chefe do Poder Executivo."]]'::jsonb,'C',2023,687,NULL,NULL,'{"regra":"A resolução deve aplicar a regra orçamentária, financeira ou contábil pública pertinente ao tema, respeitando a classificação e o estágio indicados no enunciado.","passos":["Identifique o núcleo do tema: AFO, Direito Financeiro e Contabilidade Pública - Gestão Patrimonial (arts. 43 a 47 da LRF).","Aplique a regra ao caso concreto e elimine as alternativas incompatíveis com o conceito cobrado.","O gabarito registrado é C."],"calculo":"Quando houver valores no enunciado, a conta deve ser montada apenas com os dados fornecidos e conforme a relação conceitual indicada acima.","correta":"C — é vedada sua aplicação para o financiamento de despesa corrente, salvo se destinada por lei aos regimes de previdência social, geral e próprio dos servidores públicos.","erradas":["As demais alternativas contrariam a definição, classificação ou consequência contábil aplicável ao caso."],"fundamento":"AFO, Direito Financeiro e Contabilidade Pública - Gestão Patrimonial (arts. 43 a 47 da LRF)"}'::jsonb,'O texto seguinte servirá de base para responder a questão a seguir. Em face da pandemia de Coronavírus, o Chefe do Poder Executivo de Carcará decidiu realocar todos os servidores do Departamento de Recursos Humanos para o regime de teletrabalho, motivo pelo qual prédio que ocupavam tornou-se inservível para a administração. Diante disso, o Prefeito pediu autorização à Câmara Mu') ON CONFLICT (id) DO UPDATE SET prioridade_base=EXCLUDED.prioridade_base, prioridade_faixa=EXCLUDED.prioridade_faixa, topic=EXCLUDED.topic, origin=EXCLUDED.origin, file_source=EXCLUDED.file_source, stem=EXCLUDED.stem, options=EXCLUDED.options, answer=EXCLUDED.answer, year=EXCLUDED.year, qnum=EXCLUDED.qnum, score=EXCLUDED.score, band=EXCLUDED.band, resolution=EXCLUDED.resolution, summary=EXCLUDED.summary;
INSERT INTO public.questoes (id,rank,prioridade_base,prioridade_faixa,topic,origin,file_source,stem,options,answer,year,qnum,score,band,resolution,summary) VALUES ('3600651',2263,75,'P2','AFO, Direito Financeiro e Contabilidade Pública - Escrituração e Consolidação (arts. 50 e 51 da LRF)','FAFIPA - Cont (Pref Paranavaí)/Pref Paranavaí/2025','Caderno Contabilidade Pública Parte 4','A Lei de Responsabilidade Fiscal (LRF) estabelece regras para a escrituração e consolidação das contas públicas, visando o controle e o equilíbrio das finanças dos entes federados. Considerando disposições contidas na LRF acerca da Escrituração e Consolidação das Contas, assinale a alternativa INCORRETA.','[["A","As receitas e despesas previdenciárias serão apresentadas em demonstrativos financeiros e orçamentários específicos."],["B","A despesa e a assunção de compromisso serão registradas segundo o regime de competência, apurando-se, em caráter complementar, o resultado dos fluxos financeiros pelo regime de caixa."],["C","As demonstrações contábeis compreenderão, isolada e conjuntamente, as transações e operações de cada órgão, fundo ou entidade da administração direta, autárquica e fundacional, inclusive empresa estatal dependente."],["D","A disponibilidade de caixa constará de registro próprio, de modo que os recursos vinculados a órgão, fundo ou despesa obrigatória fiquem identificados e escriturados de forma individualizada."],["E","O balanço orçamentário dará destaque à origem e ao destino dos recursos provenientes da alienação de ativos."]]'::jsonb,'E',2025,688,NULL,NULL,'{"regra":"A resolução deve aplicar a regra orçamentária, financeira ou contábil pública pertinente ao tema, respeitando a classificação e o estágio indicados no enunciado.","passos":["Identifique o núcleo do tema: AFO, Direito Financeiro e Contabilidade Pública - Escrituração e Consolidação (arts. 50 e 51 da LRF).","Aplique a regra ao caso concreto e elimine as alternativas incompatíveis com o conceito cobrado.","O gabarito registrado é E."],"calculo":"Quando houver valores no enunciado, a conta deve ser montada apenas com os dados fornecidos e conforme a relação conceitual indicada acima.","correta":"E — O balanço orçamentário dará destaque à origem e ao destino dos recursos provenientes da alienação de ativos.","erradas":["As demais alternativas contrariam a definição, classificação ou consequência contábil aplicável ao caso."],"fundamento":"AFO, Direito Financeiro e Contabilidade Pública - Escrituração e Consolidação (arts. 50 e 51 da LRF)"}'::jsonb,'A Lei de Responsabilidade Fiscal (LRF) estabelece regras para a escrituração e consolidação das contas públicas, visando o controle e o equilíbrio das finanças dos entes federados. Considerando disposições contidas na LRF acerca da Escrituração e Consolidação das Contas, assinale a alternativa INCORRETA.') ON CONFLICT (id) DO UPDATE SET prioridade_base=EXCLUDED.prioridade_base, prioridade_faixa=EXCLUDED.prioridade_faixa, topic=EXCLUDED.topic, origin=EXCLUDED.origin, file_source=EXCLUDED.file_source, stem=EXCLUDED.stem, options=EXCLUDED.options, answer=EXCLUDED.answer, year=EXCLUDED.year, qnum=EXCLUDED.qnum, score=EXCLUDED.score, band=EXCLUDED.band, resolution=EXCLUDED.resolution, summary=EXCLUDED.summary;
INSERT INTO public.questoes (id,rank,prioridade_base,prioridade_faixa,topic,origin,file_source,stem,options,answer,year,qnum,score,band,resolution,summary) VALUES ('3081971',2264,72,'P2','AFO, Direito Financeiro e Contabilidade Pública - Escrituração e Consolidação (arts. 50 e 51 da LRF)','FAFIPA - Aud Fisc Trib (Londrina)/Pref Londrina/2015','Caderno Contabilidade Pública Parte 4','As normas de finanças públicas voltadas para a responsabilidade na gestão fiscal previstas na Lei Complementar n° 101 estabelece e define no art. n° 50 define a Escrituração e Consolidação das Contas que além de obedecer às demais normas de contabilidade pública, a escrituração das contas públicas observará as seguintes regras: A disponibilidade de caixa constará de registro próprio, de modo que os recursos vinculados a órgão, fundo ou despesa obrigatória fiquem identificados e escriturados de forma individualizada. Certo Errado','[]'::jsonb,'C',2015,689,NULL,NULL,'{"regra":"A resolução deve aplicar a regra orçamentária, financeira ou contábil pública pertinente ao tema, respeitando a classificação e o estágio indicados no enunciado.","passos":["Identifique o núcleo do tema: AFO, Direito Financeiro e Contabilidade Pública - Escrituração e Consolidação (arts. 50 e 51 da LRF).","Aplique a regra ao caso concreto e elimine as alternativas incompatíveis com o conceito cobrado.","O gabarito registrado é C."],"calculo":"Quando houver valores no enunciado, a conta deve ser montada apenas com os dados fornecidos e conforme a relação conceitual indicada acima.","correta":"C — conforme o gabarito registrado no caderno.","erradas":["As demais alternativas contrariam a definição, classificação ou consequência contábil aplicável ao caso."],"fundamento":"AFO, Direito Financeiro e Contabilidade Pública - Escrituração e Consolidação (arts. 50 e 51 da LRF)"}'::jsonb,'As normas de finanças públicas voltadas para a responsabilidade na gestão fiscal previstas na Lei Complementar n° 101 estabelece e define no art. n° 50 define a Escrituração e Consolidação das Contas que além de obedecer às demais normas de contabilidade pública, a escrituração das contas públicas observará as seguintes regras: A disponibilidade de caixa constará de registro pr') ON CONFLICT (id) DO UPDATE SET prioridade_base=EXCLUDED.prioridade_base, prioridade_faixa=EXCLUDED.prioridade_faixa, topic=EXCLUDED.topic, origin=EXCLUDED.origin, file_source=EXCLUDED.file_source, stem=EXCLUDED.stem, options=EXCLUDED.options, answer=EXCLUDED.answer, year=EXCLUDED.year, qnum=EXCLUDED.qnum, score=EXCLUDED.score, band=EXCLUDED.band, resolution=EXCLUDED.resolution, summary=EXCLUDED.summary;
INSERT INTO public.questoes (id,rank,prioridade_base,prioridade_faixa,topic,origin,file_source,stem,options,answer,year,qnum,score,band,resolution,summary) VALUES ('3133142',2265,72,'P2','AFO, Direito Financeiro e Contabilidade Pública - Escrituração e Consolidação (arts. 50 e 51 da LRF)','FAFIPA - Aud Int (Pref Londrina)/Pref Londrina/Serviço de Auditoria Institucional/2015','Caderno Contabilidade Pública Parte 4','As normas de finanças públicas voltadas para a responsabilidade na gestão fiscal previstas na Lei Complementar n° 101 estabelece e define no art. n° 50 define a Escrituração e Consolidação das Contas que além de obedecer às demais normas de contabilidade pública, a escrituração das contas públicas observará a seguinte regra: A despesa e a assunção de compromisso serão registradas segundo o regime de caixa, apurando-se, em caráter complementar, o resultado dos fluxos financeiros pelo regime de competência. Certo Errado','[]'::jsonb,'E',2015,690,NULL,NULL,'{"regra":"A resolução deve aplicar a regra orçamentária, financeira ou contábil pública pertinente ao tema, respeitando a classificação e o estágio indicados no enunciado.","passos":["Identifique o núcleo do tema: AFO, Direito Financeiro e Contabilidade Pública - Escrituração e Consolidação (arts. 50 e 51 da LRF).","Aplique a regra ao caso concreto e elimine as alternativas incompatíveis com o conceito cobrado.","O gabarito registrado é E."],"calculo":"Quando houver valores no enunciado, a conta deve ser montada apenas com os dados fornecidos e conforme a relação conceitual indicada acima.","correta":"E — conforme o gabarito registrado no caderno.","erradas":["As demais alternativas contrariam a definição, classificação ou consequência contábil aplicável ao caso."],"fundamento":"AFO, Direito Financeiro e Contabilidade Pública - Escrituração e Consolidação (arts. 50 e 51 da LRF)"}'::jsonb,'As normas de finanças públicas voltadas para a responsabilidade na gestão fiscal previstas na Lei Complementar n° 101 estabelece e define no art. n° 50 define a Escrituração e Consolidação das Contas que além de obedecer às demais normas de contabilidade pública, a escrituração das contas públicas observará a seguinte regra: A despesa e a assunção de compromisso serão registrad') ON CONFLICT (id) DO UPDATE SET prioridade_base=EXCLUDED.prioridade_base, prioridade_faixa=EXCLUDED.prioridade_faixa, topic=EXCLUDED.topic, origin=EXCLUDED.origin, file_source=EXCLUDED.file_source, stem=EXCLUDED.stem, options=EXCLUDED.options, answer=EXCLUDED.answer, year=EXCLUDED.year, qnum=EXCLUDED.qnum, score=EXCLUDED.score, band=EXCLUDED.band, resolution=EXCLUDED.resolution, summary=EXCLUDED.summary;
INSERT INTO public.questoes (id,rank,prioridade_base,prioridade_faixa,topic,origin,file_source,stem,options,answer,year,qnum,score,band,resolution,summary) VALUES ('3708663',2266,85,'P1','AFO, Direito Financeiro e Contabilidade Pública - Ativo Imobilizado (MCASP e NBC TSP 07)','FAFIPA - Cont (CM Pinhais)/CM Pinhais/2025','Caderno Contabilidade Pública Parte 4','A NBC TSP 07 estabelece o tratamento contábil para ativos imobilizados, de forma que os usuários das demonstrações contábeis possam discernir a informação sobre o investimento da entidade em seus ativos imobilizados, bem como suas variações. Com base nessa referida Norma, assinale a alternativa que NÃO corresponde a um exemplo de gasto que integra o custo de um ativo imobilizado.','[["A","Gastos com transferência das atividades para novo local."],["B","Custos de benefícios a empregados decorrentes diretamente da construção de item do ativo imobilizado."],["C","Custos de instalação e montagem."],["D","Custos de preparação do local."],["E","Gastos com honorários profissionais."]]'::jsonb,'A',2025,691,NULL,NULL,'{"regra":"A resolução deve aplicar a regra orçamentária, financeira ou contábil pública pertinente ao tema, respeitando a classificação e o estágio indicados no enunciado.","passos":["Identifique o núcleo do tema: AFO, Direito Financeiro e Contabilidade Pública - Ativo Imobilizado (MCASP e NBC TSP 07).","Aplique a regra ao caso concreto e elimine as alternativas incompatíveis com o conceito cobrado.","O gabarito registrado é A."],"calculo":"Quando houver valores no enunciado, a conta deve ser montada apenas com os dados fornecidos e conforme a relação conceitual indicada acima.","correta":"A — Gastos com transferência das atividades para novo local.","erradas":["As demais alternativas contrariam a definição, classificação ou consequência contábil aplicável ao caso."],"fundamento":"AFO, Direito Financeiro e Contabilidade Pública - Ativo Imobilizado (MCASP e NBC TSP 07)"}'::jsonb,'A NBC TSP 07 estabelece o tratamento contábil para ativos imobilizados, de forma que os usuários das demonstrações contábeis possam discernir a informação sobre o investimento da entidade em seus ativos imobilizados, bem como suas variações. Com base nessa referida Norma, assinale a alternativa que NÃO corresponde a um exemplo de gasto que integra o custo de um ativo imobilizad') ON CONFLICT (id) DO UPDATE SET prioridade_base=EXCLUDED.prioridade_base, prioridade_faixa=EXCLUDED.prioridade_faixa, topic=EXCLUDED.topic, origin=EXCLUDED.origin, file_source=EXCLUDED.file_source, stem=EXCLUDED.stem, options=EXCLUDED.options, answer=EXCLUDED.answer, year=EXCLUDED.year, qnum=EXCLUDED.qnum, score=EXCLUDED.score, band=EXCLUDED.band, resolution=EXCLUDED.resolution, summary=EXCLUDED.summary;
INSERT INTO public.questoes (id,rank,prioridade_base,prioridade_faixa,topic,origin,file_source,stem,options,answer,year,qnum,score,band,resolution,summary) VALUES ('3423401',2267,84,'P1','AFO, Direito Financeiro e Contabilidade Pública - Ativo Imobilizado (MCASP e NBC TSP 07)','FAFIPA - Cont (CM Paiçandu)/CM Paiçandu/2024','Caderno Contabilidade Pública Parte 4','Considerando as disposições contidas no Manual de Contabilidade Aplicada ao Setor Público, assinale a alternativa INCORRETA.','[["A","Valor liquido contábil é o valor do bem registrado na contabilidade, em determinada data, deduzido da correspondente depreciação, amortização ou exaustão acumulada, bem como das perdas acumuladas por redução ao valor recuperável."],["B","Valor recuperável é o maior montante entre o valor justo líquido de despesas de venda do ativo ou da unidade geradora de caixa e o seu valor em uso."],["C","Avaliação patrimonial é a atribuição de valor monetário a itens do ativo e do passivo decorrentes de Julgamento fundamentado em consenso entre as partes e que traduza, com razoabilidade, a evidenciação dos atos e dos fatos administrativos."],["D","Valor realizável líquido é o valor do bem registrado na contabilidade, em uma determinada data, sem a dedução da correspondente depreciação, amortização ou exaustão acumulada."]]'::jsonb,'D',2024,692,NULL,NULL,'{"regra":"A resolução deve aplicar a regra orçamentária, financeira ou contábil pública pertinente ao tema, respeitando a classificação e o estágio indicados no enunciado.","passos":["Identifique o núcleo do tema: AFO, Direito Financeiro e Contabilidade Pública - Ativo Imobilizado (MCASP e NBC TSP 07).","Aplique a regra ao caso concreto e elimine as alternativas incompatíveis com o conceito cobrado.","O gabarito registrado é D."],"calculo":"Quando houver valores no enunciado, a conta deve ser montada apenas com os dados fornecidos e conforme a relação conceitual indicada acima.","correta":"D — Valor realizável líquido é o valor do bem registrado na contabilidade, em uma determinada data, sem a dedução da correspondente depreciação, amortização ou exaustão acumulada.","erradas":["As demais alternativas contrariam a definição, classificação ou consequência contábil aplicável ao caso."],"fundamento":"AFO, Direito Financeiro e Contabilidade Pública - Ativo Imobilizado (MCASP e NBC TSP 07)"}'::jsonb,'Considerando as disposições contidas no Manual de Contabilidade Aplicada ao Setor Público, assinale a alternativa INCORRETA.') ON CONFLICT (id) DO UPDATE SET prioridade_base=EXCLUDED.prioridade_base, prioridade_faixa=EXCLUDED.prioridade_faixa, topic=EXCLUDED.topic, origin=EXCLUDED.origin, file_source=EXCLUDED.file_source, stem=EXCLUDED.stem, options=EXCLUDED.options, answer=EXCLUDED.answer, year=EXCLUDED.year, qnum=EXCLUDED.qnum, score=EXCLUDED.score, band=EXCLUDED.band, resolution=EXCLUDED.resolution, summary=EXCLUDED.summary;
INSERT INTO public.questoes (id,rank,prioridade_base,prioridade_faixa,topic,origin,file_source,stem,options,answer,year,qnum,score,band,resolution,summary) VALUES ('3680349',2268,83,'P1','AFO, Direito Financeiro e Contabilidade Pública - Ativo Imobilizado (MCASP e NBC TSP 07)','FAFIPA - Cont (CM SJ Pinhais)/CM SJ dos Pinhais/2023','Caderno Contabilidade Pública Parte 4','O texto seguinte servirá de base para responder a questão a seguir. Em face da pandemia de Coronavírus, o Chefe do Poder Executivo de Carcará decidiu realocar todos os servidores do Departamento de Recursos Humanos para o regime de teletrabalho, motivo pelo qual prédio que ocupavam tornou-se inservível para a administração. Diante disso, o Prefeito pediu autorização à Câmara Municipal para alienar o prédio, que foi concedida através de Lei em30/11/2021. Seis meses depois, o Leilão foi realizado, e o imóvel foi arrematado à vista por R$175.000,00. Na mesma data, o valor contábil líquido do ativo era de R$ 155.000,00. Diante do caso descrito, é CORRETO afirmar que, diante da intenção de vender o prédio, o Ativo em questão deverá ser reclassificado:','[["A","para o grupo Ativo Circulante, subgrupo Investimentos."],["B","para o grupo Ativo Circulante, subgrupo Ativo Não Circulante Mantido para Venda."],["C","para o grupo Ativo Não Circulante, subgrupo Ativo Não Circulante Mantido para Venda."],["D","para o grupo Ativo Circulante, subgrupo Estoques."],["E","para o grupo Ativo Não Circulante, subgrupo Investimentos."]]'::jsonb,'B',2023,693,NULL,NULL,'{"regra":"A resolução deve aplicar a regra orçamentária, financeira ou contábil pública pertinente ao tema, respeitando a classificação e o estágio indicados no enunciado.","passos":["Identifique o núcleo do tema: AFO, Direito Financeiro e Contabilidade Pública - Ativo Imobilizado (MCASP e NBC TSP 07).","Aplique a regra ao caso concreto e elimine as alternativas incompatíveis com o conceito cobrado.","O gabarito registrado é B."],"calculo":"Quando houver valores no enunciado, a conta deve ser montada apenas com os dados fornecidos e conforme a relação conceitual indicada acima.","correta":"B — para o grupo Ativo Circulante, subgrupo Ativo Não Circulante Mantido para Venda.","erradas":["As demais alternativas contrariam a definição, classificação ou consequência contábil aplicável ao caso."],"fundamento":"AFO, Direito Financeiro e Contabilidade Pública - Ativo Imobilizado (MCASP e NBC TSP 07)"}'::jsonb,'O texto seguinte servirá de base para responder a questão a seguir. Em face da pandemia de Coronavírus, o Chefe do Poder Executivo de Carcará decidiu realocar todos os servidores do Departamento de Recursos Humanos para o regime de teletrabalho, motivo pelo qual prédio que ocupavam tornou-se inservível para a administração. Diante disso, o Prefeito pediu autorização à Câmara Mu') ON CONFLICT (id) DO UPDATE SET prioridade_base=EXCLUDED.prioridade_base, prioridade_faixa=EXCLUDED.prioridade_faixa, topic=EXCLUDED.topic, origin=EXCLUDED.origin, file_source=EXCLUDED.file_source, stem=EXCLUDED.stem, options=EXCLUDED.options, answer=EXCLUDED.answer, year=EXCLUDED.year, qnum=EXCLUDED.qnum, score=EXCLUDED.score, band=EXCLUDED.band, resolution=EXCLUDED.resolution, summary=EXCLUDED.summary;
INSERT INTO public.questoes (id,rank,prioridade_base,prioridade_faixa,topic,origin,file_source,stem,options,answer,year,qnum,score,band,resolution,summary) VALUES ('967025',2269,82,'P1','AFO, Direito Financeiro e Contabilidade Pública - Redução ao Valor Recuperável (MCASP, NBC TSP 09 e 10)','FAFIPA - Cont (CM Palmeira)/CM Palmeira/2015','Caderno Contabilidade Pública Parte 4','Considerando os conceitos aplicados ao Ativo das Entidades do setor público, o valor de mercado de um ativo menos o custo para a sua alienação, ou o valor que a entidade do setor público espera recuperar pelo uso futuro desse ativo nas suas operações, o que for maior, é denominado como:','[["A","Valor recuperável."],["B","Valor justo."],["C","Valor realizável líquido."],["D","Avaliação patrimonial."]]'::jsonb,'A',2015,694,NULL,NULL,'{"regra":"A resolução deve aplicar a regra orçamentária, financeira ou contábil pública pertinente ao tema, respeitando a classificação e o estágio indicados no enunciado.","passos":["Identifique o núcleo do tema: AFO, Direito Financeiro e Contabilidade Pública - Redução ao Valor Recuperável (MCASP, NBC TSP 09 e 10).","Aplique a regra ao caso concreto e elimine as alternativas incompatíveis com o conceito cobrado.","O gabarito registrado é A."],"calculo":"Quando houver valores no enunciado, a conta deve ser montada apenas com os dados fornecidos e conforme a relação conceitual indicada acima.","correta":"A — Valor recuperável.","erradas":["As demais alternativas contrariam a definição, classificação ou consequência contábil aplicável ao caso."],"fundamento":"AFO, Direito Financeiro e Contabilidade Pública - Redução ao Valor Recuperável (MCASP, NBC TSP 09 e 10)"}'::jsonb,'Considerando os conceitos aplicados ao Ativo das Entidades do setor público, o valor de mercado de um ativo menos o custo para a sua alienação, ou o valor que a entidade do setor público espera recuperar pelo uso futuro desse ativo nas suas operações, o que for maior, é denominado como:') ON CONFLICT (id) DO UPDATE SET prioridade_base=EXCLUDED.prioridade_base, prioridade_faixa=EXCLUDED.prioridade_faixa, topic=EXCLUDED.topic, origin=EXCLUDED.origin, file_source=EXCLUDED.file_source, stem=EXCLUDED.stem, options=EXCLUDED.options, answer=EXCLUDED.answer, year=EXCLUDED.year, qnum=EXCLUDED.qnum, score=EXCLUDED.score, band=EXCLUDED.band, resolution=EXCLUDED.resolution, summary=EXCLUDED.summary;
INSERT INTO public.questoes (id,rank,prioridade_base,prioridade_faixa,topic,origin,file_source,stem,options,answer,year,qnum,score,band,resolution,summary) VALUES ('926997',2270,82,'P1','AFO, Direito Financeiro e Contabilidade Pública - Redução ao Valor Recuperável (MCASP, NBC TSP 09 e 10)','FAFIPA - Con (CM Paranapoema)/CM Paranapoema/2014','Caderno Contabilidade Pública Parte 4','A entidade deve avaliar se há alguma indicação de que um ativo imobilizado ou intangível possa ter sofrido perda. Caso o valor contábil de um ativo imobilizado ou intangível apresente valor acima do valor justo por meio do uso ou da venda desse ativo, é possível afirmar que esse ativo está em imparidade (impairment). O impairment é a desvalorização de um ativo quando seu valor contábil excede o valor justo, ou seja, representa a perda dos futuros benefícios econômicos ou do potencial de serviços de um ativo, além da depreciação. Segundo o Manual de Contabilidade do Setor Público – MCASP, assinale a alternativa que contém a associação CORRETA com esta afirmativa:','[["A","Redução ao Valor Recuperável."],["B","Reavaliação."],["C","Ajuste de Avaliação Patrimonial."],["D","Amortização."]]'::jsonb,'A',2014,695,NULL,NULL,'{"regra":"A resolução deve aplicar a regra orçamentária, financeira ou contábil pública pertinente ao tema, respeitando a classificação e o estágio indicados no enunciado.","passos":["Identifique o núcleo do tema: AFO, Direito Financeiro e Contabilidade Pública - Redução ao Valor Recuperável (MCASP, NBC TSP 09 e 10).","Aplique a regra ao caso concreto e elimine as alternativas incompatíveis com o conceito cobrado.","O gabarito registrado é A."],"calculo":"Quando houver valores no enunciado, a conta deve ser montada apenas com os dados fornecidos e conforme a relação conceitual indicada acima.","correta":"A — Redução ao Valor Recuperável.","erradas":["As demais alternativas contrariam a definição, classificação ou consequência contábil aplicável ao caso."],"fundamento":"AFO, Direito Financeiro e Contabilidade Pública - Redução ao Valor Recuperável (MCASP, NBC TSP 09 e 10)"}'::jsonb,'A entidade deve avaliar se há alguma indicação de que um ativo imobilizado ou intangível possa ter sofrido perda. Caso o valor contábil de um ativo imobilizado ou intangível apresente valor acima do valor justo por meio do uso ou da venda desse ativo, é possível afirmar que esse ativo está em imparidade (impairment). O impairment é a desvalorização de um ativo quando seu valor ') ON CONFLICT (id) DO UPDATE SET prioridade_base=EXCLUDED.prioridade_base, prioridade_faixa=EXCLUDED.prioridade_faixa, topic=EXCLUDED.topic, origin=EXCLUDED.origin, file_source=EXCLUDED.file_source, stem=EXCLUDED.stem, options=EXCLUDED.options, answer=EXCLUDED.answer, year=EXCLUDED.year, qnum=EXCLUDED.qnum, score=EXCLUDED.score, band=EXCLUDED.band, resolution=EXCLUDED.resolution, summary=EXCLUDED.summary;
INSERT INTO public.questoes (id,rank,prioridade_base,prioridade_faixa,topic,origin,file_source,stem,options,answer,year,qnum,score,band,resolution,summary) VALUES ('3599113',2271,75,'P2','AFO, Direito Financeiro e Contabilidade Pública - Transparência da Gestão Fiscal (arts. 48 e 49 da LRF)','FAFIPA - Cont (CICA)/CICA/2025','Caderno Contabilidade Pública Parte 4','Segundo a Lei de Responsabilidade Fiscal, são instrumentos de transparência da gestão fiscal, aos quais será dada ampla divulgação, inclusive em meios eletrônicos de acesso público, EXCETO:','[["A","as versões amplificadas do Relatório Resumido da Execução Orçamentária e do Relatório de Gestão Fiscal."],["B","os planos, orçamentos e leis de diretrizes orçamentárias."],["C","o Relatório Resumido da Execução Orçamentária e o Relatório de Gestão Fiscal."],["D","as prestações de contas e o respectivo parecer prévio."]]'::jsonb,'A',2025,696,NULL,NULL,'{"regra":"A resolução deve aplicar a regra orçamentária, financeira ou contábil pública pertinente ao tema, respeitando a classificação e o estágio indicados no enunciado.","passos":["Identifique o núcleo do tema: AFO, Direito Financeiro e Contabilidade Pública - Transparência da Gestão Fiscal (arts. 48 e 49 da LRF).","Aplique a regra ao caso concreto e elimine as alternativas incompatíveis com o conceito cobrado.","O gabarito registrado é A."],"calculo":"Quando houver valores no enunciado, a conta deve ser montada apenas com os dados fornecidos e conforme a relação conceitual indicada acima.","correta":"A — as versões amplificadas do Relatório Resumido da Execução Orçamentária e do Relatório de Gestão Fiscal.","erradas":["As demais alternativas contrariam a definição, classificação ou consequência contábil aplicável ao caso."],"fundamento":"AFO, Direito Financeiro e Contabilidade Pública - Transparência da Gestão Fiscal (arts. 48 e 49 da LRF)"}'::jsonb,'Segundo a Lei de Responsabilidade Fiscal, são instrumentos de transparência da gestão fiscal, aos quais será dada ampla divulgação, inclusive em meios eletrônicos de acesso público, EXCETO:') ON CONFLICT (id) DO UPDATE SET prioridade_base=EXCLUDED.prioridade_base, prioridade_faixa=EXCLUDED.prioridade_faixa, topic=EXCLUDED.topic, origin=EXCLUDED.origin, file_source=EXCLUDED.file_source, stem=EXCLUDED.stem, options=EXCLUDED.options, answer=EXCLUDED.answer, year=EXCLUDED.year, qnum=EXCLUDED.qnum, score=EXCLUDED.score, band=EXCLUDED.band, resolution=EXCLUDED.resolution, summary=EXCLUDED.summary;
INSERT INTO public.questoes (id,rank,prioridade_base,prioridade_faixa,topic,origin,file_source,stem,options,answer,year,qnum,score,band,resolution,summary) VALUES ('3600649',2272,75,'P2','AFO, Direito Financeiro e Contabilidade Pública - Transparência da Gestão Fiscal (arts. 48 e 49 da LRF)','FAFIPA - Cont (Pref Paranavaí)/Pref Paranavaí/2025','Caderno Contabilidade Pública Parte 4','A transparência na Lei de Responsabilidade Fiscal (LRF) visa garantir que a sociedade tenha acesso a informações sobre a gestão fiscal dos governos, permitindo o controle social e a responsabilização dos gestores públicos. A LRF exige a divulgação de relatórios e demonstrações, como o Relatório de Gestão Fiscal (RGF) e o Relatório Resumido da Execução Orçamentária (RREE), que detalham a execução orçamentária e financeira. Acerca da Transparência da Gestão Fiscal contida na LRF, assinale a alternativa INCORRETA.','[["A","Atransparência será assegurada mediante ao incentivo à participação popular e realização de audiências públicas, durante os processos de elaboração e discussão dos planos, lei de diretrizes orçamentárias e orçamentos."],["B","Atransparência será assegurada mediante a liberação ao pleno conhecimento e acompanhamento da sociedade, em tempo real, de informações pormenorizadas sobre a execução orçamentária e financeira, em meios eletrônicos de acesso público."],["C","A União, os Estados, o Distrito Federal e os Municípios disponibilizarão suas informações e dados contábeis, orçamentários e fiscais conforme periodicidade, formato e sistema estabelecidos pelo órgão central de contabilidade da União, os quais deverão ser divulgados em meio eletrônico de amplo acesso público."],["D","A transparência será assegurada mediante a adoção do Sistema Integrado de Administração Financeira e Controle, que atenda a padrão mínimo de qualidade estabelecido pelo Poder Executivo da União."],["E","Os Estados, o Distrito Federal e os Municípios encaminharão ao Tribunal de Contas da União, nos termos e na periodicidade a serem definidos em instrução específica deste órgão, as informações necessárias para a constituição do registro eletrônico centralizado e atualizado das dívidas públicas interna e externa."]]'::jsonb,'E',2025,697,NULL,NULL,'{"regra":"A resolução deve aplicar a regra orçamentária, financeira ou contábil pública pertinente ao tema, respeitando a classificação e o estágio indicados no enunciado.","passos":["Identifique o núcleo do tema: AFO, Direito Financeiro e Contabilidade Pública - Transparência da Gestão Fiscal (arts. 48 e 49 da LRF).","Aplique a regra ao caso concreto e elimine as alternativas incompatíveis com o conceito cobrado.","O gabarito registrado é E."],"calculo":"Quando houver valores no enunciado, a conta deve ser montada apenas com os dados fornecidos e conforme a relação conceitual indicada acima.","correta":"E — Os Estados, o Distrito Federal e os Municípios encaminharão ao Tribunal de Contas da União, nos termos e na periodicidade a serem definidos em instrução específica deste órgão, as informações necessárias para a constituição do registro eletrônico centralizado e atualizado das dívidas públicas interna e externa.","erradas":["As demais alternativas contrariam a definição, classificação ou consequência contábil aplicável ao caso."],"fundamento":"AFO, Direito Financeiro e Contabilidade Pública - Transparência da Gestão Fiscal (arts. 48 e 49 da LRF)"}'::jsonb,'A transparência na Lei de Responsabilidade Fiscal (LRF) visa garantir que a sociedade tenha acesso a informações sobre a gestão fiscal dos governos, permitindo o controle social e a responsabilização dos gestores públicos. A LRF exige a divulgação de relatórios e demonstrações, como o Relatório de Gestão Fiscal (RGF) e o Relatório Resumido da Execução Orçamentária (RREE), que d') ON CONFLICT (id) DO UPDATE SET prioridade_base=EXCLUDED.prioridade_base, prioridade_faixa=EXCLUDED.prioridade_faixa, topic=EXCLUDED.topic, origin=EXCLUDED.origin, file_source=EXCLUDED.file_source, stem=EXCLUDED.stem, options=EXCLUDED.options, answer=EXCLUDED.answer, year=EXCLUDED.year, qnum=EXCLUDED.qnum, score=EXCLUDED.score, band=EXCLUDED.band, resolution=EXCLUDED.resolution, summary=EXCLUDED.summary;
INSERT INTO public.questoes (id,rank,prioridade_base,prioridade_faixa,topic,origin,file_source,stem,options,answer,year,qnum,score,band,resolution,summary) VALUES ('4074906',2273,88,'P1','AFO, Direito Financeiro e Contabilidade Pública - Relatório Resumido da Execução Orçamentária - RREO (arts. 52 e 53 da LRF)','FAFIPA - Tes (CM Campo Largo)/CM Campo Largo/2026','Caderno Contabilidade Pública Parte 4','No acompanhamento da execução orçamentária municipal, o setor de tesouraria recebeu solicitação para informar o prazo constitucional de publicação do Relatório Resumido da Execução Orçamentária. Nos termos da Constituição Federal e da Lei de Responsabilidade Fiscal, o Relatório Resumido da Execução Orçamentária deve ser publicado:','[["A","até quinze dias após o encerramento de cada mês."],["B","até sessenta dias após o encerramento de cada semestre."],["C","até o último dia útil do exercício seguinte."],["D","até noventa dias após o encerramento do exercício financeiro."],["E","até trinta dias após o encerramento de cada bimestre."]]'::jsonb,'E',2026,698,NULL,NULL,'{"regra":"A resolução deve aplicar a regra orçamentária, financeira ou contábil pública pertinente ao tema, respeitando a classificação e o estágio indicados no enunciado.","passos":["Identifique o núcleo do tema: AFO, Direito Financeiro e Contabilidade Pública - Relatório Resumido da Execução Orçamentária - RREO (arts. 52 e 53 da LRF).","Aplique a regra ao caso concreto e elimine as alternativas incompatíveis com o conceito cobrado.","O gabarito registrado é E."],"calculo":"Quando houver valores no enunciado, a conta deve ser montada apenas com os dados fornecidos e conforme a relação conceitual indicada acima.","correta":"E — até trinta dias após o encerramento de cada bimestre.","erradas":["As demais alternativas contrariam a definição, classificação ou consequência contábil aplicável ao caso."],"fundamento":"AFO, Direito Financeiro e Contabilidade Pública - Relatório Resumido da Execução Orçamentária - RREO (arts. 52 e 53 da LRF)"}'::jsonb,'No acompanhamento da execução orçamentária municipal, o setor de tesouraria recebeu solicitação para informar o prazo constitucional de publicação do Relatório Resumido da Execução Orçamentária. Nos termos da Constituição Federal e da Lei de Responsabilidade Fiscal, o Relatório Resumido da Execução Orçamentária deve ser publicado:') ON CONFLICT (id) DO UPDATE SET prioridade_base=EXCLUDED.prioridade_base, prioridade_faixa=EXCLUDED.prioridade_faixa, topic=EXCLUDED.topic, origin=EXCLUDED.origin, file_source=EXCLUDED.file_source, stem=EXCLUDED.stem, options=EXCLUDED.options, answer=EXCLUDED.answer, year=EXCLUDED.year, qnum=EXCLUDED.qnum, score=EXCLUDED.score, band=EXCLUDED.band, resolution=EXCLUDED.resolution, summary=EXCLUDED.summary;
INSERT INTO public.questoes (id,rank,prioridade_base,prioridade_faixa,topic,origin,file_source,stem,options,answer,year,qnum,score,band,resolution,summary) VALUES ('966929',2274,84,'P1','AFO, Direito Financeiro e Contabilidade Pública - Relatório Resumido da Execução Orçamentária - RREO (arts. 52 e 53 da LRF)','FAFIPA - TAd (Tijucas S Prev)/Tijucas do Sul Prev/2015','Caderno Contabilidade Pública Parte 4','A Lei Complementar nº 101/2000 dispõe sobre as normas reguladoras das finanças públicas no nosso país, visando à transparência e o equilíbrio fiscal nas contas públicas, inclusive solicitando o levantamento e prestação de diversas informações sobre a administração das contas públicas. Dentre os diversos documentos da Gestão Fiscal, o Relatório Resumido da Execução Orçamentária abrangerá todos os Poderes e o Ministério Público, trazendo uma série de informações sobre a gestão fiscal, além de um demonstrativo contábil exigido pela Contabilidade Pública. Este Demonstrativo é:','[["A","A Demonstração de Lucros do Exercício."],["B","A Demonstração do Fluxo de Caixa Indireta."],["C","O Balanço Orçamentário."],["D","A Demonstração dos Lucros e Prejuízos Acumulados."],["E","A Demonstração do Valor Adicionado."]]'::jsonb,'C',2015,699,NULL,NULL,'{"regra":"A resolução deve aplicar a regra orçamentária, financeira ou contábil pública pertinente ao tema, respeitando a classificação e o estágio indicados no enunciado.","passos":["Identifique o núcleo do tema: AFO, Direito Financeiro e Contabilidade Pública - Relatório Resumido da Execução Orçamentária - RREO (arts. 52 e 53 da LRF).","Aplique a regra ao caso concreto e elimine as alternativas incompatíveis com o conceito cobrado.","O gabarito registrado é C."],"calculo":"Quando houver valores no enunciado, a conta deve ser montada apenas com os dados fornecidos e conforme a relação conceitual indicada acima.","correta":"C — O Balanço Orçamentário.","erradas":["As demais alternativas contrariam a definição, classificação ou consequência contábil aplicável ao caso."],"fundamento":"AFO, Direito Financeiro e Contabilidade Pública - Relatório Resumido da Execução Orçamentária - RREO (arts. 52 e 53 da LRF)"}'::jsonb,'A Lei Complementar nº 101/2000 dispõe sobre as normas reguladoras das finanças públicas no nosso país, visando à transparência e o equilíbrio fiscal nas contas públicas, inclusive solicitando o levantamento e prestação de diversas informações sobre a administração das contas públicas. Dentre os diversos documentos da Gestão Fiscal, o Relatório Resumido da Execução Orçamentária ') ON CONFLICT (id) DO UPDATE SET prioridade_base=EXCLUDED.prioridade_base, prioridade_faixa=EXCLUDED.prioridade_faixa, topic=EXCLUDED.topic, origin=EXCLUDED.origin, file_source=EXCLUDED.file_source, stem=EXCLUDED.stem, options=EXCLUDED.options, answer=EXCLUDED.answer, year=EXCLUDED.year, qnum=EXCLUDED.qnum, score=EXCLUDED.score, band=EXCLUDED.band, resolution=EXCLUDED.resolution, summary=EXCLUDED.summary;
INSERT INTO public.questoes (id,rank,prioridade_base,prioridade_faixa,topic,origin,file_source,stem,options,answer,year,qnum,score,band,resolution,summary) VALUES ('4074907',2275,88,'P1','AFO, Direito Financeiro e Contabilidade Pública - Relatório de Gestão Fiscal - RGF (arts. 54 e 55 da LRF)','FAFIPA - Tes (CM Campo Largo)/CM Campo Largo/2026','Caderno Contabilidade Pública Parte 4','Ao final de determinado quadrimestre, o responsável pelo setor financeiro de um Município que não se enquadra na hipótese de divulgação semestral prevista na Lei de Responsabilidade Fiscal foi consultado sobre o prazo de divulgação do Relatório de Gestão Fiscal, instrumento utilizado para acompanhar limites e condições da gestão fiscal responsável. Nos termos da Lei de Responsabilidade Fiscal, o Relatório de Gestão Fiscal deve ser publicado:','[["A","até quinze dias antes da publicação da Lei Orçamentária Anual."],["B","somente ao final de cada exercício, juntamente com o Balanço Geral."],["C","até o último dia do exercício financeiro."],["D","até trinta dias após o encerramento do período a que corresponder."],["E","até noventa dias após o encerramento de cada semestre."]]'::jsonb,'D',2026,700,NULL,NULL,'{"regra":"A resolução deve aplicar a regra orçamentária, financeira ou contábil pública pertinente ao tema, respeitando a classificação e o estágio indicados no enunciado.","passos":["Identifique o núcleo do tema: AFO, Direito Financeiro e Contabilidade Pública - Relatório de Gestão Fiscal - RGF (arts. 54 e 55 da LRF).","Aplique a regra ao caso concreto e elimine as alternativas incompatíveis com o conceito cobrado.","O gabarito registrado é D."],"calculo":"Quando houver valores no enunciado, a conta deve ser montada apenas com os dados fornecidos e conforme a relação conceitual indicada acima.","correta":"D — até trinta dias após o encerramento do período a que corresponder.","erradas":["As demais alternativas contrariam a definição, classificação ou consequência contábil aplicável ao caso."],"fundamento":"AFO, Direito Financeiro e Contabilidade Pública - Relatório de Gestão Fiscal - RGF (arts. 54 e 55 da LRF)"}'::jsonb,'Ao final de determinado quadrimestre, o responsável pelo setor financeiro de um Município que não se enquadra na hipótese de divulgação semestral prevista na Lei de Responsabilidade Fiscal foi consultado sobre o prazo de divulgação do Relatório de Gestão Fiscal, instrumento utilizado para acompanhar limites e condições da gestão fiscal responsável. Nos termos da Lei de Responsa') ON CONFLICT (id) DO UPDATE SET prioridade_base=EXCLUDED.prioridade_base, prioridade_faixa=EXCLUDED.prioridade_faixa, topic=EXCLUDED.topic, origin=EXCLUDED.origin, file_source=EXCLUDED.file_source, stem=EXCLUDED.stem, options=EXCLUDED.options, answer=EXCLUDED.answer, year=EXCLUDED.year, qnum=EXCLUDED.qnum, score=EXCLUDED.score, band=EXCLUDED.band, resolution=EXCLUDED.resolution, summary=EXCLUDED.summary;
INSERT INTO public.questoes (id,rank,prioridade_base,prioridade_faixa,topic,origin,file_source,stem,options,answer,year,qnum,score,band,resolution,summary) VALUES ('3862441',2276,87,'P1','AFO, Direito Financeiro e Contabilidade Pública - Relatório de Gestão Fiscal - RGF (arts. 54 e 55 da LRF)','FAFIPA - Cont (Pref Jundiaí do Sul)/Pref Jundiaí do Sul/2025','Caderno Contabilidade Pública Parte 4','A Lei de Responsabilidade Fiscal estabelece limites e condições para a contratação de operações de crédito pelos entes federativos, incluindo as operações por antecipação de receita orçamentária (ARO). Caso o Município de Jundiaí do Sul realize uma ARO, deverá apresentar demonstrativo específico comprovando o cumprimento do limite legal aplicável a esse tipo de operação. Esse demonstrativo integra obrigatoriamente o:','[["A","Relatório de Gestão Fiscal."],["B","Relatório de Transparência Fiscal."],["C","Relatório Resumido da Execução Orçamentária."],["D","Anexo de Metas Fiscais."],["E","Relatório de Limite Fiscal."]]'::jsonb,'A',2025,701,NULL,NULL,'{"regra":"A resolução deve aplicar a regra orçamentária, financeira ou contábil pública pertinente ao tema, respeitando a classificação e o estágio indicados no enunciado.","passos":["Identifique o núcleo do tema: AFO, Direito Financeiro e Contabilidade Pública - Relatório de Gestão Fiscal - RGF (arts. 54 e 55 da LRF).","Aplique a regra ao caso concreto e elimine as alternativas incompatíveis com o conceito cobrado.","O gabarito registrado é A."],"calculo":"Quando houver valores no enunciado, a conta deve ser montada apenas com os dados fornecidos e conforme a relação conceitual indicada acima.","correta":"A — Relatório de Gestão Fiscal.","erradas":["As demais alternativas contrariam a definição, classificação ou consequência contábil aplicável ao caso."],"fundamento":"AFO, Direito Financeiro e Contabilidade Pública - Relatório de Gestão Fiscal - RGF (arts. 54 e 55 da LRF)"}'::jsonb,'A Lei de Responsabilidade Fiscal estabelece limites e condições para a contratação de operações de crédito pelos entes federativos, incluindo as operações por antecipação de receita orçamentária (ARO). Caso o Município de Jundiaí do Sul realize uma ARO, deverá apresentar demonstrativo específico comprovando o cumprimento do limite legal aplicável a esse tipo de operação. Esse d') ON CONFLICT (id) DO UPDATE SET prioridade_base=EXCLUDED.prioridade_base, prioridade_faixa=EXCLUDED.prioridade_faixa, topic=EXCLUDED.topic, origin=EXCLUDED.origin, file_source=EXCLUDED.file_source, stem=EXCLUDED.stem, options=EXCLUDED.options, answer=EXCLUDED.answer, year=EXCLUDED.year, qnum=EXCLUDED.qnum, score=EXCLUDED.score, band=EXCLUDED.band, resolution=EXCLUDED.resolution, summary=EXCLUDED.summary;
INSERT INTO public.questoes (id,rank,prioridade_base,prioridade_faixa,topic,origin,file_source,stem,options,answer,year,qnum,score,band,resolution,summary) VALUES ('3460683',2277,75,'P2','AFO, Direito Financeiro e Contabilidade Pública - Procedimentos Contábeis Específicos (RPPS, FUNDEB, etc.)','FAFIPA - Ana Prev (FOZPREV)/FOZPREV/Ciências Contábeis/2025','Caderno Contabilidade Pública Parte 4','Com base no Manual de Contabilidade Aplicada ao Setor Público – 10ª Edição, é CORRETO afirmar que as contribuições previdenciárias patronais do Poder Executivo Municipal repassadas ao RPPS devem ser classificadas como:','[["A","despesas correntes intraorçamentárias, a modalidade de aplicação 41 - Transferências a Municípios - Fundo a Fundo."],["B","despesas correntes intraorçamentárias, na modalidade de aplicação 91 - Aplicação Direta Decorrente de Operação entre Órgãos, Fundos e Entidades Integrantes do Orçamento Fiscal e do Orçamento da Seguridade Social."],["C","despesas extraorçamentárias, na modalidade de aplicação 91 - Aplicação Direta Decorrente de Operação entre Órgãos, Fundos e Entidades Integrantes do Orçamento Fiscal e do Orçamento da Seguridade Social."],["D","despesas correntes, na modalidade de aplicação 90 - Aplicação Direta."]]'::jsonb,'B',2025,702,NULL,NULL,'{"regra":"A resolução deve aplicar a regra orçamentária, financeira ou contábil pública pertinente ao tema, respeitando a classificação e o estágio indicados no enunciado.","passos":["Identifique o núcleo do tema: AFO, Direito Financeiro e Contabilidade Pública - Procedimentos Contábeis Específicos (RPPS, FUNDEB, etc.).","Aplique a regra ao caso concreto e elimine as alternativas incompatíveis com o conceito cobrado.","O gabarito registrado é B."],"calculo":"Quando houver valores no enunciado, a conta deve ser montada apenas com os dados fornecidos e conforme a relação conceitual indicada acima.","correta":"B — despesas correntes intraorçamentárias, na modalidade de aplicação 91 - Aplicação Direta Decorrente de Operação entre Órgãos, Fundos e Entidades Integrantes do Orçamento Fiscal e do Orçamento da Seguridade Social.","erradas":["As demais alternativas contrariam a definição, classificação ou consequência contábil aplicável ao caso."],"fundamento":"AFO, Direito Financeiro e Contabilidade Pública - Procedimentos Contábeis Específicos (RPPS, FUNDEB, etc.)"}'::jsonb,'Com base no Manual de Contabilidade Aplicada ao Setor Público – 10ª Edição, é CORRETO afirmar que as contribuições previdenciárias patronais do Poder Executivo Municipal repassadas ao RPPS devem ser classificadas como:') ON CONFLICT (id) DO UPDATE SET prioridade_base=EXCLUDED.prioridade_base, prioridade_faixa=EXCLUDED.prioridade_faixa, topic=EXCLUDED.topic, origin=EXCLUDED.origin, file_source=EXCLUDED.file_source, stem=EXCLUDED.stem, options=EXCLUDED.options, answer=EXCLUDED.answer, year=EXCLUDED.year, qnum=EXCLUDED.qnum, score=EXCLUDED.score, band=EXCLUDED.band, resolution=EXCLUDED.resolution, summary=EXCLUDED.summary;
INSERT INTO public.questoes (id,rank,prioridade_base,prioridade_faixa,topic,origin,file_source,stem,options,answer,year,qnum,score,band,resolution,summary) VALUES ('2156998',2278,73,'P2','AFO, Direito Financeiro e Contabilidade Pública - Procedimentos Contábeis Específicos (RPPS, FUNDEB, etc.)','FAFIPA - Con (RPPS Palmeira)/RPPS Palmeira PR/2022','Caderno Contabilidade Pública Parte 4','A Instrução de Procedimentos Contábeis - IPC 14, que estabelece os Procedimentos Contábeis Relativos aos RPPS - Regimes Próprios de Previdência Social, define que as características gerais do plano de previdência e os principais resultados da avaliação atuarial do mesmo devem ser registradas de forma resumida e prestadas anualmente por meio do:','[["A","Demonstrativo da Política de Investimento (DPIN)."],["B","Demonstrativo do Resultado da Avaliação Atuarial (DRAA)."],["C","Demonstrativo da Aplicação e Investimentos dos Recursos (DAIR)."],["D","Demonstrativo de Informações Previdenciárias e Repasses (DIPR)."]]'::jsonb,'B',2022,703,NULL,NULL,'{"regra":"A resolução deve aplicar a regra orçamentária, financeira ou contábil pública pertinente ao tema, respeitando a classificação e o estágio indicados no enunciado.","passos":["Identifique o núcleo do tema: AFO, Direito Financeiro e Contabilidade Pública - Procedimentos Contábeis Específicos (RPPS, FUNDEB, etc.).","Aplique a regra ao caso concreto e elimine as alternativas incompatíveis com o conceito cobrado.","O gabarito registrado é B."],"calculo":"Quando houver valores no enunciado, a conta deve ser montada apenas com os dados fornecidos e conforme a relação conceitual indicada acima.","correta":"B — Demonstrativo do Resultado da Avaliação Atuarial (DRAA).","erradas":["As demais alternativas contrariam a definição, classificação ou consequência contábil aplicável ao caso."],"fundamento":"AFO, Direito Financeiro e Contabilidade Pública - Procedimentos Contábeis Específicos (RPPS, FUNDEB, etc.)"}'::jsonb,'A Instrução de Procedimentos Contábeis - IPC 14, que estabelece os Procedimentos Contábeis Relativos aos RPPS - Regimes Próprios de Previdência Social, define que as características gerais do plano de previdência e os principais resultados da avaliação atuarial do mesmo devem ser registradas de forma resumida e prestadas anualmente por meio do:') ON CONFLICT (id) DO UPDATE SET prioridade_base=EXCLUDED.prioridade_base, prioridade_faixa=EXCLUDED.prioridade_faixa, topic=EXCLUDED.topic, origin=EXCLUDED.origin, file_source=EXCLUDED.file_source, stem=EXCLUDED.stem, options=EXCLUDED.options, answer=EXCLUDED.answer, year=EXCLUDED.year, qnum=EXCLUDED.qnum, score=EXCLUDED.score, band=EXCLUDED.band, resolution=EXCLUDED.resolution, summary=EXCLUDED.summary;
INSERT INTO public.questoes (id,rank,prioridade_base,prioridade_faixa,topic,origin,file_source,stem,options,answer,year,qnum,score,band,resolution,summary) VALUES ('3708621',2279,85,'P1','AFO, Direito Financeiro e Contabilidade Pública - NBC TSP 34 - Custos no Setor Público','FAFIPA - Cont (CM Pinhais)/CM Pinhais/2025','Caderno Contabilidade Pública Parte 4','A NBC TSP 34 – Custos no Setor Público, estabelece diretrizes e padrões a serem observados na implementação do sistema de custos. Trata de critériospara geração da informação de custos, como instrumento de governança pública, e aponta para o importante papel do gestor na adoção efetiva de modelos de gerenciamento de custos. Considerando as disposições da referida Norma, assinale a alternativa CORRETA.','[["A","Sistema de informação de custos é o conjunto de elementos estruturados que registra, processa e evidencia os custos de bens e serviços e demais objetos de custos."],["B","Sistema de acumulação compreende o modelo de gerenciamento de custos, o sistema de informação de custos e a definição de funções e responsabilidades organizacionais com o intuito de gerar informações de custos como instrumento de governança pública."],["C","Sistema de custos corresponde à forma como os custos são acumulados e atribuídos aos bens e serviços e outros objetos de custos e está relacionado aofluxo físico e real da produção."],["D","Sistema de acumulação contínua é o conjunto de mecanismos de liderança, estratégia e controle postos em prática para avaliar, direcionar e monitorar a gestão, com vistas à condução de políticas públicas e à prestação de serviços de interesse da sociedade."],["E","Sistema de acumulação por ordem de serviço ou produção se refere ao método de atribuição de custos e está associado ao processo de identificação do custo ao objeto que está sendo custeado."]]'::jsonb,'A',2025,704,NULL,NULL,'{"regra":"A resolução deve aplicar a regra orçamentária, financeira ou contábil pública pertinente ao tema, respeitando a classificação e o estágio indicados no enunciado.","passos":["Identifique o núcleo do tema: AFO, Direito Financeiro e Contabilidade Pública - NBC TSP 34 - Custos no Setor Público.","Aplique a regra ao caso concreto e elimine as alternativas incompatíveis com o conceito cobrado.","O gabarito registrado é A."],"calculo":"Quando houver valores no enunciado, a conta deve ser montada apenas com os dados fornecidos e conforme a relação conceitual indicada acima.","correta":"A — Sistema de informação de custos é o conjunto de elementos estruturados que registra, processa e evidencia os custos de bens e serviços e demais objetos de custos.","erradas":["As demais alternativas contrariam a definição, classificação ou consequência contábil aplicável ao caso."],"fundamento":"AFO, Direito Financeiro e Contabilidade Pública - NBC TSP 34 - Custos no Setor Público"}'::jsonb,'A NBC TSP 34 – Custos no Setor Público, estabelece diretrizes e padrões a serem observados na implementação do sistema de custos. Trata de critériospara geração da informação de custos, como instrumento de governança pública, e aponta para o importante papel do gestor na adoção efetiva de modelos de gerenciamento de custos. Considerando as disposições da referida Norma, assinal') ON CONFLICT (id) DO UPDATE SET prioridade_base=EXCLUDED.prioridade_base, prioridade_faixa=EXCLUDED.prioridade_faixa, topic=EXCLUDED.topic, origin=EXCLUDED.origin, file_source=EXCLUDED.file_source, stem=EXCLUDED.stem, options=EXCLUDED.options, answer=EXCLUDED.answer, year=EXCLUDED.year, qnum=EXCLUDED.qnum, score=EXCLUDED.score, band=EXCLUDED.band, resolution=EXCLUDED.resolution, summary=EXCLUDED.summary;
INSERT INTO public.questoes (id,rank,prioridade_base,prioridade_faixa,topic,origin,file_source,stem,options,answer,year,qnum,score,band,resolution,summary) VALUES ('3708641',2280,85,'P1','AFO, Direito Financeiro e Contabilidade Pública - NBC TSP 34 - Custos no Setor Público','FAFIPA - Cont (CM Pinhais)/CM Pinhais/2025','Caderno Contabilidade Pública Parte 4','De acordo NBC TSP 34 – Custos no Setor Público, o apoio da alta administração é imprescindível para implementar modelo de gerenciamento de custos que propicie a utilização da informação de custos como ferramenta de auxílio aos processos de planejamento, tomada de decisão, monitoramento, avaliação de desempenho, transparência, prestação de contas e responsabilização. Considerando as disposições da referida Norma, assinale a alternativa INCORRETA.','[["A","O profissional de contabilidade da entidade é responsável por definir e estruturar os centros de responsabilidade e custo."],["B","A geração das informações de custo é atribuição do profissional da contabilidade, mas a integridade e fidedignidade das informações extraídas das bases de dados de origem são de responsabilidade dos gestores das transações registradas nos sistemas integrados ao sistema de informação de custos."],["C","A alta administração é responsável por prover efetivo apoio à geração da informação de custos, além de responsabilizar os gestores pela qualidade dos dados e pelo uso das informações nos processos decisórios."],["D","A atribuição dos custos aos objetos de custos se dá mediante aplicação dos sistemas de acumulação e dos métodos de custeio."],["E","A definição dos objetos de custos deve considerar, principalmente, as necessidades e os propósitos dos usuários da informação."]]'::jsonb,'A',2025,705,NULL,NULL,'{"regra":"A resolução deve aplicar a regra orçamentária, financeira ou contábil pública pertinente ao tema, respeitando a classificação e o estágio indicados no enunciado.","passos":["Identifique o núcleo do tema: AFO, Direito Financeiro e Contabilidade Pública - NBC TSP 34 - Custos no Setor Público.","Aplique a regra ao caso concreto e elimine as alternativas incompatíveis com o conceito cobrado.","O gabarito registrado é A."],"calculo":"Quando houver valores no enunciado, a conta deve ser montada apenas com os dados fornecidos e conforme a relação conceitual indicada acima.","correta":"A — O profissional de contabilidade da entidade é responsável por definir e estruturar os centros de responsabilidade e custo.","erradas":["As demais alternativas contrariam a definição, classificação ou consequência contábil aplicável ao caso."],"fundamento":"AFO, Direito Financeiro e Contabilidade Pública - NBC TSP 34 - Custos no Setor Público"}'::jsonb,'De acordo NBC TSP 34 – Custos no Setor Público, o apoio da alta administração é imprescindível para implementar modelo de gerenciamento de custos que propicie a utilização da informação de custos como ferramenta de auxílio aos processos de planejamento, tomada de decisão, monitoramento, avaliação de desempenho, transparência, prestação de contas e responsabilização. Considerand') ON CONFLICT (id) DO UPDATE SET prioridade_base=EXCLUDED.prioridade_base, prioridade_faixa=EXCLUDED.prioridade_faixa, topic=EXCLUDED.topic, origin=EXCLUDED.origin, file_source=EXCLUDED.file_source, stem=EXCLUDED.stem, options=EXCLUDED.options, answer=EXCLUDED.answer, year=EXCLUDED.year, qnum=EXCLUDED.qnum, score=EXCLUDED.score, band=EXCLUDED.band, resolution=EXCLUDED.resolution, summary=EXCLUDED.summary;
INSERT INTO public.questoes (id,rank,prioridade_base,prioridade_faixa,topic,origin,file_source,stem,options,answer,year,qnum,score,band,resolution,summary) VALUES ('2415456',2281,73,'P2','AFO, Direito Financeiro e Contabilidade Pública - Conceito e Natureza Jurídica do Orçamento Público','FAFIPA - Cont (TIBAGIPREV)/TIBAGIPREV/2022','Caderno Contabilidade Pública Parte 4','Orçamento público é um plano governamental que se renova a cada ano, envolvendo os interesses da população em geral, independentemente de classe social, além dos interesses dos setores produtivos do país, como a agricultura, a indústria e os serviços. Atualmente, o orçamento deixou de ser mero documento de caráter contábil e administrativo, para espelhar toda a vida econômica da sociedade, constituindo-se em um importante instrumento dinâmico do estado a orientar sua atuação sobre a economia. Considerando as características do orçamento público, analise as afirmativas a seguir: I. Funciona como um plano para ordenar e coordenar o funcionamento estatal, direcionando e dando previsibilidade às ações governamentais. II. O particular não detém condições de tomar decisões, haja vista que o orçamento público tem um caráter sigiloso, devendo seu controle e seu acompanhamento serem feitos pelo respectivo órgão público. III. É um instrumento hábil que produz influências na economia e na sociedade, conforme os interesses e as ações do poder público. IV. É um mecanismo utilizado para organizar as receitas e despesas públicas, que são considerados meios para a concretização dos planos governamentais. Assinale a alternativa com as assertivas CORRETAS:','[["A","I, II e III, apenas."],["B","I, III e IV, apenas."],["C","I, II e IV, apenas."],["D","II, III e IV, apenas."],["E","I, II, III e IV."]]'::jsonb,'B',2022,706,NULL,NULL,'{"regra":"A resolução deve aplicar a regra orçamentária, financeira ou contábil pública pertinente ao tema, respeitando a classificação e o estágio indicados no enunciado.","passos":["Identifique o núcleo do tema: AFO, Direito Financeiro e Contabilidade Pública - Conceito e Natureza Jurídica do Orçamento Público.","Aplique a regra ao caso concreto e elimine as alternativas incompatíveis com o conceito cobrado.","O gabarito registrado é B."],"calculo":"Quando houver valores no enunciado, a conta deve ser montada apenas com os dados fornecidos e conforme a relação conceitual indicada acima.","correta":"B — I, III e IV, apenas.","erradas":["As demais alternativas contrariam a definição, classificação ou consequência contábil aplicável ao caso."],"fundamento":"AFO, Direito Financeiro e Contabilidade Pública - Conceito e Natureza Jurídica do Orçamento Público"}'::jsonb,'Orçamento público é um plano governamental que se renova a cada ano, envolvendo os interesses da população em geral, independentemente de classe social, além dos interesses dos setores produtivos do país, como a agricultura, a indústria e os serviços. Atualmente, o orçamento deixou de ser mero documento de caráter contábil e administrativo, para espelhar toda a vida econômica d') ON CONFLICT (id) DO UPDATE SET prioridade_base=EXCLUDED.prioridade_base, prioridade_faixa=EXCLUDED.prioridade_faixa, topic=EXCLUDED.topic, origin=EXCLUDED.origin, file_source=EXCLUDED.file_source, stem=EXCLUDED.stem, options=EXCLUDED.options, answer=EXCLUDED.answer, year=EXCLUDED.year, qnum=EXCLUDED.qnum, score=EXCLUDED.score, band=EXCLUDED.band, resolution=EXCLUDED.resolution, summary=EXCLUDED.summary;
INSERT INTO public.questoes (id,rank,prioridade_base,prioridade_faixa,topic,origin,file_source,stem,options,answer,year,qnum,score,band,resolution,summary) VALUES ('917577',2282,72,'P2','AFO, Direito Financeiro e Contabilidade Pública - Dívida Fundada e Dívida Flutuante - Conceitos Gerais','FAFIPA - Ass Leg (CM Toledo)/CM Toledo (PR)/2014','Caderno Contabilidade Pública Parte 4','Considerando a Lei nº. 4.320, de 17 de março de 1964, analise as afirmativas, a seguir. Dívida flutuante compreende: I. Os restos a pagar, excluídos os serviços da dívida. II. Os serviços da dívida a pagar. III. Os depósitos. IV. Os débitos de tesouraria. Está(ão) CORRETA( S) as afirmativas:','[["A","Apenas a afirmativa II está correta."],["B","As afirmativas I e III estão corretas."],["C","As afirmativas III e IV estão corretas."],["D","Todas as afirmativas estão corretas."]]'::jsonb,'D',2014,707,NULL,NULL,'{"regra":"A resolução deve aplicar a regra orçamentária, financeira ou contábil pública pertinente ao tema, respeitando a classificação e o estágio indicados no enunciado.","passos":["Identifique o núcleo do tema: AFO, Direito Financeiro e Contabilidade Pública - Dívida Fundada e Dívida Flutuante - Conceitos Gerais.","Aplique a regra ao caso concreto e elimine as alternativas incompatíveis com o conceito cobrado.","O gabarito registrado é D."],"calculo":"Quando houver valores no enunciado, a conta deve ser montada apenas com os dados fornecidos e conforme a relação conceitual indicada acima.","correta":"D — Todas as afirmativas estão corretas.","erradas":["As demais alternativas contrariam a definição, classificação ou consequência contábil aplicável ao caso."],"fundamento":"AFO, Direito Financeiro e Contabilidade Pública - Dívida Fundada e Dívida Flutuante - Conceitos Gerais"}'::jsonb,'Considerando a Lei nº. 4.320, de 17 de março de 1964, analise as afirmativas, a seguir. Dívida flutuante compreende: I. Os restos a pagar, excluídos os serviços da dívida. II. Os serviços da dívida a pagar. III. Os depósitos. IV. Os débitos de tesouraria. Está(ão) CORRETA( S) as afirmativas:') ON CONFLICT (id) DO UPDATE SET prioridade_base=EXCLUDED.prioridade_base, prioridade_faixa=EXCLUDED.prioridade_faixa, topic=EXCLUDED.topic, origin=EXCLUDED.origin, file_source=EXCLUDED.file_source, stem=EXCLUDED.stem, options=EXCLUDED.options, answer=EXCLUDED.answer, year=EXCLUDED.year, qnum=EXCLUDED.qnum, score=EXCLUDED.score, band=EXCLUDED.band, resolution=EXCLUDED.resolution, summary=EXCLUDED.summary;
INSERT INTO public.questoes (id,rank,prioridade_base,prioridade_faixa,topic,origin,file_source,stem,options,answer,year,qnum,score,band,resolution,summary) VALUES ('563459',2283,72,'P2','AFO, Direito Financeiro e Contabilidade Pública - Conceitos Gerais sobre Despesa Pública','FAFIPA - Tec NS (FA)/FA/2017','Caderno Contabilidade Pública Parte 4','Analise as assertivas abaixo. I. Despesa pública pode ser definida como o conjunto de gastos do Estado, cujo objetivo é promover a realização de necessidades públicas, o que implica o correto funcionamento e desenvolvimento de serviços públicos e manutenção da estrutura administrativa necessária para tanto. II. É pressuposto de toda e qualquer despesa não apenas a indicação da fonte respectiva de financiamento, ou seja, a receita que lhe fará frente, mas, também, a autorização do Poder Legislativo. III. Os créditos adicionais são autorizações de despesas não computadas no orçamento ou dotadas no orçamento de forma insuficiente. IV. As despesas correntes são aquelas resultantes da manutenção das atividades próprias do Estado, tais como o custeio da estrutura administrativa. Estão CORRETAS as assertivas:','[["A","II e IV."],["B","I e II."],["C","I, III, IV."],["D","I, II, III, IV."]]'::jsonb,'D',2017,708,NULL,NULL,'{"regra":"A resolução deve aplicar a regra orçamentária, financeira ou contábil pública pertinente ao tema, respeitando a classificação e o estágio indicados no enunciado.","passos":["Identifique o núcleo do tema: AFO, Direito Financeiro e Contabilidade Pública - Conceitos Gerais sobre Despesa Pública.","Aplique a regra ao caso concreto e elimine as alternativas incompatíveis com o conceito cobrado.","O gabarito registrado é D."],"calculo":"Quando houver valores no enunciado, a conta deve ser montada apenas com os dados fornecidos e conforme a relação conceitual indicada acima.","correta":"D — I, II, III, IV.","erradas":["As demais alternativas contrariam a definição, classificação ou consequência contábil aplicável ao caso."],"fundamento":"AFO, Direito Financeiro e Contabilidade Pública - Conceitos Gerais sobre Despesa Pública"}'::jsonb,'Analise as assertivas abaixo. I. Despesa pública pode ser definida como o conjunto de gastos do Estado, cujo objetivo é promover a realização de necessidades públicas, o que implica o correto funcionamento e desenvolvimento de serviços públicos e manutenção da estrutura administrativa necessária para tanto. II. É pressuposto de toda e qualquer despesa não apenas a indicação da ') ON CONFLICT (id) DO UPDATE SET prioridade_base=EXCLUDED.prioridade_base, prioridade_faixa=EXCLUDED.prioridade_faixa, topic=EXCLUDED.topic, origin=EXCLUDED.origin, file_source=EXCLUDED.file_source, stem=EXCLUDED.stem, options=EXCLUDED.options, answer=EXCLUDED.answer, year=EXCLUDED.year, qnum=EXCLUDED.qnum, score=EXCLUDED.score, band=EXCLUDED.band, resolution=EXCLUDED.resolution, summary=EXCLUDED.summary;
INSERT INTO public.questoes (id,rank,prioridade_base,prioridade_faixa,topic,origin,file_source,stem,options,answer,year,qnum,score,band,resolution,summary) VALUES ('938454',2284,82,'P1','AFO, Direito Financeiro e Contabilidade Pública - Depreciação, Amortização e Exaustão (NBC TSP 07, MCASP, etc.)','FAFIPA - CI (CM A Tamandaré)/CM Alm. Tamandaré/2016','Caderno Contabilidade Pública Parte 4','O Manual de Contabilidade do Setor Público (MCASP) estabelece critérios de avaliação de ativos e passivos. Determinados bens encontrados no ativo imobilizado estarão sujeitos a este procedimento. Tais bens são aqueles explorados através da extração ou aproveitamento mineral ou florestal, por exemplo, uma floresta mantida com fins de comercialização de madeira. Dessa forma, esta avaliação do ativo permitirá ao ente que o custo do ativo seja distribuído durante o período de extração/aproveitamento. Para esse fim, é necessário que haja uma análise técnica da capacidade de extração/aproveitamento do ativo em questão, pois seu reconhecimento se dará proporcionalmente à quantidade produzida pelo ativo. Esses conceitos estão relacionados com a:','[["A","Depreciação."],["B","Amortização."],["C","Exaustão."],["D","Reavaliação."]]'::jsonb,'C',2016,709,NULL,NULL,'{"regra":"A resolução deve aplicar a regra orçamentária, financeira ou contábil pública pertinente ao tema, respeitando a classificação e o estágio indicados no enunciado.","passos":["Identifique o núcleo do tema: AFO, Direito Financeiro e Contabilidade Pública - Depreciação, Amortização e Exaustão (NBC TSP 07, MCASP, etc.).","Aplique a regra ao caso concreto e elimine as alternativas incompatíveis com o conceito cobrado.","O gabarito registrado é C."],"calculo":"Quando houver valores no enunciado, a conta deve ser montada apenas com os dados fornecidos e conforme a relação conceitual indicada acima.","correta":"C — Exaustão.","erradas":["As demais alternativas contrariam a definição, classificação ou consequência contábil aplicável ao caso."],"fundamento":"AFO, Direito Financeiro e Contabilidade Pública - Depreciação, Amortização e Exaustão (NBC TSP 07, MCASP, etc.)"}'::jsonb,'O Manual de Contabilidade do Setor Público (MCASP) estabelece critérios de avaliação de ativos e passivos. Determinados bens encontrados no ativo imobilizado estarão sujeitos a este procedimento. Tais bens são aqueles explorados através da extração ou aproveitamento mineral ou florestal, por exemplo, uma floresta mantida com fins de comercialização de madeira. Dessa forma, esta') ON CONFLICT (id) DO UPDATE SET prioridade_base=EXCLUDED.prioridade_base, prioridade_faixa=EXCLUDED.prioridade_faixa, topic=EXCLUDED.topic, origin=EXCLUDED.origin, file_source=EXCLUDED.file_source, stem=EXCLUDED.stem, options=EXCLUDED.options, answer=EXCLUDED.answer, year=EXCLUDED.year, qnum=EXCLUDED.qnum, score=EXCLUDED.score, band=EXCLUDED.band, resolution=EXCLUDED.resolution, summary=EXCLUDED.summary;
INSERT INTO public.questoes (id,rank,prioridade_base,prioridade_faixa,topic,origin,file_source,stem,options,answer,year,qnum,score,band,resolution,summary) VALUES ('3862430',2285,85,'P1','AFO, Direito Financeiro e Contabilidade Pública - Ativo Intangível (MCASP e NBC TSP 08)','FAFIPA - Cont (Pref Jundiaí do Sul)/Pref Jundiaí do Sul/2025','Caderno Contabilidade Pública Parte 4','Durante uma conferência de rotina, o contador do município X identificou que foi registrada a depreciação sobre um ativo intangível de duração limitada no tempo, qual seja, o software utilizado pela Controladoria Geral do Município, cujo prazo contratual de vigência é de 15 anos. Considerando as normas contábeis aplicáveis, assinale a alternativa CORRETA.','[["A","A contabilização correta seria registrar exaustão, visto que se trata de ativo intangível com vida útil definida."],["B","A prática é adequada, pois a depreciação representa a redução do valor do ativo intangível ao longo do tempo."],["C","A contabilização está incorreta, visto que o ativo intangível deveria estar registrado com vida útil indefinida."],["D","O ativo intangível não pode sofrer amortização, depreciação ou exaustão, pois deve passar por testes de impairment."],["E","A contabilização está incorreta, visto que o ativo intangível com vida útil definida deve ser amortizado."]]'::jsonb,'E',2025,710,NULL,NULL,'{"regra":"A resolução deve aplicar a regra orçamentária, financeira ou contábil pública pertinente ao tema, respeitando a classificação e o estágio indicados no enunciado.","passos":["Identifique o núcleo do tema: AFO, Direito Financeiro e Contabilidade Pública - Ativo Intangível (MCASP e NBC TSP 08).","Aplique a regra ao caso concreto e elimine as alternativas incompatíveis com o conceito cobrado.","O gabarito registrado é E."],"calculo":"Quando houver valores no enunciado, a conta deve ser montada apenas com os dados fornecidos e conforme a relação conceitual indicada acima.","correta":"E — A contabilização está incorreta, visto que o ativo intangível com vida útil definida deve ser amortizado.","erradas":["As demais alternativas contrariam a definição, classificação ou consequência contábil aplicável ao caso."],"fundamento":"AFO, Direito Financeiro e Contabilidade Pública - Ativo Intangível (MCASP e NBC TSP 08)"}'::jsonb,'Durante uma conferência de rotina, o contador do município X identificou que foi registrada a depreciação sobre um ativo intangível de duração limitada no tempo, qual seja, o software utilizado pela Controladoria Geral do Município, cujo prazo contratual de vigência é de 15 anos. Considerando as normas contábeis aplicáveis, assinale a alternativa CORRETA.') ON CONFLICT (id) DO UPDATE SET prioridade_base=EXCLUDED.prioridade_base, prioridade_faixa=EXCLUDED.prioridade_faixa, topic=EXCLUDED.topic, origin=EXCLUDED.origin, file_source=EXCLUDED.file_source, stem=EXCLUDED.stem, options=EXCLUDED.options, answer=EXCLUDED.answer, year=EXCLUDED.year, qnum=EXCLUDED.qnum, score=EXCLUDED.score, band=EXCLUDED.band, resolution=EXCLUDED.resolution, summary=EXCLUDED.summary;
INSERT INTO public.questoes (id,rank,prioridade_base,prioridade_faixa,topic,origin,file_source,stem,options,answer,year,qnum,score,band,resolution,summary) VALUES ('4152838',2286,95,'P1','AFO, Direito Financeiro e Contabilidade Pública - Classificação por Natureza da Receita','IDECAN - Ana Leg (ALECE)/ALECE/Ciências Contábeis/2026','Caderno Contabilidade Pública Parte 5','Quanto à classificação da receita pública por categoria econômica, em conformidade com a Lei nº 4.320/1964 e as normas do Manual de Contabilidade Aplicada ao Setor Público (MCASP), indique a alternativa que corretamente apresenta receitas classificadas como Correntes.','[["A","Cota-parte do FPM, Receita Agropecuária e Amortização de Empréstimos."],["B","Receita Industrial, Alienação de Bens e Operações de Crédito."],["C","Receita Patrimonial, Transferências de Capital e Amortização de Empréstimos."],["D","Receita de Serviços, Receita de Contribuições e Receita Patrimonial."],["E","Receita Tributária, Operações de Crédito e Alienação de Bens."]]'::jsonb,'D',2026,1,NULL,NULL,'{"regra":"A resolução deve aplicar a regra orçamentária, financeira ou contábil pública pertinente ao tema, respeitando a classificação e o estágio indicados no enunciado.","passos":["Identifique o núcleo do tema: AFO, Direito Financeiro e Contabilidade Pública - Classificação por Natureza da Receita.","Aplique a regra ao caso concreto e elimine as alternativas incompatíveis com o conceito cobrado.","O gabarito registrado é D."],"calculo":"Quando houver valores no enunciado, a conta deve ser montada apenas com os dados fornecidos e conforme a relação conceitual indicada acima.","correta":"D — Receita de Serviços, Receita de Contribuições e Receita Patrimonial.","erradas":["As demais alternativas contrariam a definição, classificação ou consequência contábil aplicável ao caso."],"fundamento":"AFO, Direito Financeiro e Contabilidade Pública - Classificação por Natureza da Receita"}'::jsonb,'Quanto à classificação da receita pública por categoria econômica, em conformidade com a Lei nº 4.320/1964 e as normas do Manual de Contabilidade Aplicada ao Setor Público (MCASP), indique a alternativa que corretamente apresenta receitas classificadas como Correntes.') ON CONFLICT (id) DO UPDATE SET prioridade_base=EXCLUDED.prioridade_base, prioridade_faixa=EXCLUDED.prioridade_faixa, topic=EXCLUDED.topic, origin=EXCLUDED.origin, file_source=EXCLUDED.file_source, stem=EXCLUDED.stem, options=EXCLUDED.options, answer=EXCLUDED.answer, year=EXCLUDED.year, qnum=EXCLUDED.qnum, score=EXCLUDED.score, band=EXCLUDED.band, resolution=EXCLUDED.resolution, summary=EXCLUDED.summary;
INSERT INTO public.questoes (id,rank,prioridade_base,prioridade_faixa,topic,origin,file_source,stem,options,answer,year,qnum,score,band,resolution,summary) VALUES ('4159623',2287,95,'P1','AFO, Direito Financeiro e Contabilidade Pública - Classificação por Natureza da Receita','FUNDATEC - Adm (CRA RS)/CRA RS/2026','Caderno Contabilidade Pública Parte 5','Determinado ente da Federação, observados os limites e as condições estabelecidos pela legislação de finanças públicas e pela autorização legislativa pertinente, promoveu a emissão de títulos da dívida pública para captar recursos destinados à execução de obras de infraestrutura previstas em seu plano plurianual. Os valores captados ingressaram nos cofres públicos e foram registrados no orçamento do exercício. Nos termos da Lei nº 4.320/1964, o ingresso descrito classifica-se, quanto à categoria econômica, como:','[["A","Receita corrente, na origem receita patrimonial."],["B","Receita corrente, na origem outras receitas correntes."],["C","Receita de capital, na origem operações de crédito."],["D","Receita de capital, na origem amortização de empréstimos."]]'::jsonb,'C',2026,2,NULL,NULL,'{"regra":"A resolução deve aplicar a regra orçamentária, financeira ou contábil pública pertinente ao tema, respeitando a classificação e o estágio indicados no enunciado.","passos":["Identifique o núcleo do tema: AFO, Direito Financeiro e Contabilidade Pública - Classificação por Natureza da Receita.","Aplique a regra ao caso concreto e elimine as alternativas incompatíveis com o conceito cobrado.","O gabarito registrado é C."],"calculo":"Quando houver valores no enunciado, a conta deve ser montada apenas com os dados fornecidos e conforme a relação conceitual indicada acima.","correta":"C — Receita de capital, na origem operações de crédito.","erradas":["As demais alternativas contrariam a definição, classificação ou consequência contábil aplicável ao caso."],"fundamento":"AFO, Direito Financeiro e Contabilidade Pública - Classificação por Natureza da Receita"}'::jsonb,'Determinado ente da Federação, observados os limites e as condições estabelecidos pela legislação de finanças públicas e pela autorização legislativa pertinente, promoveu a emissão de títulos da dívida pública para captar recursos destinados à execução de obras de infraestrutura previstas em seu plano plurianual. Os valores captados ingressaram nos cofres públicos e foram regis') ON CONFLICT (id) DO UPDATE SET prioridade_base=EXCLUDED.prioridade_base, prioridade_faixa=EXCLUDED.prioridade_faixa, topic=EXCLUDED.topic, origin=EXCLUDED.origin, file_source=EXCLUDED.file_source, stem=EXCLUDED.stem, options=EXCLUDED.options, answer=EXCLUDED.answer, year=EXCLUDED.year, qnum=EXCLUDED.qnum, score=EXCLUDED.score, band=EXCLUDED.band, resolution=EXCLUDED.resolution, summary=EXCLUDED.summary;
INSERT INTO public.questoes (id,rank,prioridade_base,prioridade_faixa,topic,origin,file_source,stem,options,answer,year,qnum,score,band,resolution,summary) VALUES ('4216050',2288,95,'P1','AFO, Direito Financeiro e Contabilidade Pública - Classificação por Natureza da Receita','Instituto Verbena - FTrib (Pref Buriti Alegre)/Pref Buriti Alegre/2026','Caderno Contabilidade Pública Parte 5','Analise a tabela a seguir. Origem da Receita Valor (R$) Amortização de Empréstimos 120.000 Receita de Serviços 175.000 Outras Receitas Correntes 190.000 Outras Receitas de Capital 210.000 Receita Patrimonial 350.000 Alienação de Bens 340.000 Contribuições 610.000 Transferências de Capital 980.000 Operações de Crédito 1.800.000 Impostos, Taxas e Contribuições de 2.600.000 Melhoria Transferências Correntes 3.320.000 A receita corrente corresponde a quantas vezes a receita de capital?','[["A","0,7."],["B","1,5."],["C","2,1."],["D","2,5."]]'::jsonb,'C',2026,3,NULL,NULL,'{"regra":"A resolução deve aplicar a regra orçamentária, financeira ou contábil pública pertinente ao tema, respeitando a classificação e o estágio indicados no enunciado.","passos":["Identifique o núcleo do tema: AFO, Direito Financeiro e Contabilidade Pública - Classificação por Natureza da Receita.","Aplique a regra ao caso concreto e elimine as alternativas incompatíveis com o conceito cobrado.","O gabarito registrado é C."],"calculo":"Quando houver valores no enunciado, a conta deve ser montada apenas com os dados fornecidos e conforme a relação conceitual indicada acima.","correta":"C — 2,1.","erradas":["As demais alternativas contrariam a definição, classificação ou consequência contábil aplicável ao caso."],"fundamento":"AFO, Direito Financeiro e Contabilidade Pública - Classificação por Natureza da Receita"}'::jsonb,'Analise a tabela a seguir. Origem da Receita Valor (R$) Amortização de Empréstimos 120.000 Receita de Serviços 175.000 Outras Receitas Correntes 190.000 Outras Receitas de Capital 210.000 Receita Patrimonial 350.000 Alienação de Bens 340.000 Contribuições 610.000 Transferências de Capital 980.000 Operações de Crédito 1.800.000 Impostos, Taxas e Contribuições de 2.600.000 Melhor') ON CONFLICT (id) DO UPDATE SET prioridade_base=EXCLUDED.prioridade_base, prioridade_faixa=EXCLUDED.prioridade_faixa, topic=EXCLUDED.topic, origin=EXCLUDED.origin, file_source=EXCLUDED.file_source, stem=EXCLUDED.stem, options=EXCLUDED.options, answer=EXCLUDED.answer, year=EXCLUDED.year, qnum=EXCLUDED.qnum, score=EXCLUDED.score, band=EXCLUDED.band, resolution=EXCLUDED.resolution, summary=EXCLUDED.summary;
INSERT INTO public.questoes (id,rank,prioridade_base,prioridade_faixa,topic,origin,file_source,stem,options,answer,year,qnum,score,band,resolution,summary) VALUES ('4222092',2289,95,'P1','AFO, Direito Financeiro e Contabilidade Pública - Classificação por Natureza da Receita','FEPESE - Tec Con (Pref Itajaí)/Pref Itajaí/2026','Caderno Contabilidade Pública Parte 5','De acordo com o Manual de Contabilidade Aplicada ao Setor Público (MCASP – 11ª edição), a classificação da receita orçamentária por natureza é composta por um código de oito dígitos numéricos, com a estrutura “a.b.c.d.ee.f.g”, onde:','[["A","“a” identifica a Espécie da receita."],["B","“b” corresponde à Origem da receita."],["C","“c” corresponde ao desdobramento para identificação de peculiaridades da receita."],["D","“d” corresponde à Categoria Econômica da receita."],["E","“ee” identifica o Tipo de Receita."]]'::jsonb,'B',2026,4,NULL,NULL,'{"regra":"A resolução deve aplicar a regra orçamentária, financeira ou contábil pública pertinente ao tema, respeitando a classificação e o estágio indicados no enunciado.","passos":["Identifique o núcleo do tema: AFO, Direito Financeiro e Contabilidade Pública - Classificação por Natureza da Receita.","Aplique a regra ao caso concreto e elimine as alternativas incompatíveis com o conceito cobrado.","O gabarito registrado é B."],"calculo":"Quando houver valores no enunciado, a conta deve ser montada apenas com os dados fornecidos e conforme a relação conceitual indicada acima.","correta":"B — “b” corresponde à Origem da receita.","erradas":["As demais alternativas contrariam a definição, classificação ou consequência contábil aplicável ao caso."],"fundamento":"AFO, Direito Financeiro e Contabilidade Pública - Classificação por Natureza da Receita"}'::jsonb,'De acordo com o Manual de Contabilidade Aplicada ao Setor Público (MCASP – 11ª edição), a classificação da receita orçamentária por natureza é composta por um código de oito dígitos numéricos, com a estrutura “a.b.c.d.ee.f.g”, onde:') ON CONFLICT (id) DO UPDATE SET prioridade_base=EXCLUDED.prioridade_base, prioridade_faixa=EXCLUDED.prioridade_faixa, topic=EXCLUDED.topic, origin=EXCLUDED.origin, file_source=EXCLUDED.file_source, stem=EXCLUDED.stem, options=EXCLUDED.options, answer=EXCLUDED.answer, year=EXCLUDED.year, qnum=EXCLUDED.qnum, score=EXCLUDED.score, band=EXCLUDED.band, resolution=EXCLUDED.resolution, summary=EXCLUDED.summary;
INSERT INTO public.questoes (id,rank,prioridade_base,prioridade_faixa,topic,origin,file_source,stem,options,answer,year,qnum,score,band,resolution,summary) VALUES ('4076326',2290,73,'P2','AFO, Direito Financeiro e Contabilidade Pública - Classificação por Fonte / Destinação de Recursos','FGV - Ana (TJ SC)/TJ SC/Contábil-Econômico/2026','Caderno Contabilidade Pública Parte 5','As normas relativas às Fontes ou Destinações de Recursos disciplinam a vinculação de determinadas receitas públicas e orientam sua adequada aplicação no orçamento. Entre essas receitas, destacam-se os royalties e as participações especiais decorrentes da exploração de recursos naturais, cuja utilização observa regras específicas. Considerando esse contexto, assinale a afirmativa correta.','[["A","A classificação por Fonte ou Destinação de Recursos possui finalidade exclusivamente estatística, não produzindo efeitos sobre a execução da despesa pública."],["B","As receitas de royalties do petróleo, por possuírem natureza tributária, submetem-se integralmente ao princípio da não vinculação das receitas de impostos."],["C","A Fonte ou Destinação de Recursos funciona como mecanismo integrador entre receita e despesa, permitindo identificar vinculações legais e assegurar a aplicação dos recursos conforme sua finalidade normativa."],["D","A codificação das Fontes ou Destinações de Recursos é definida autonomamente por cada ente federativo, inexistindo padronização nacional estabelecida pela Secretaria do Tesouro Nacional."],["E","As receitas oriundas de royalties e participações especiais independem de identificação específica por fonte ou destinação, uma vez que constituem receitas ordinárias de livre aplicação."]]'::jsonb,'C',2026,5,NULL,NULL,'{"regra":"A resolução deve aplicar a regra orçamentária, financeira ou contábil pública pertinente ao tema, respeitando a classificação e o estágio indicados no enunciado.","passos":["Identifique o núcleo do tema: AFO, Direito Financeiro e Contabilidade Pública - Classificação por Fonte / Destinação de Recursos.","Aplique a regra ao caso concreto e elimine as alternativas incompatíveis com o conceito cobrado.","O gabarito registrado é C."],"calculo":"Quando houver valores no enunciado, a conta deve ser montada apenas com os dados fornecidos e conforme a relação conceitual indicada acima.","correta":"C — A Fonte ou Destinação de Recursos funciona como mecanismo integrador entre receita e despesa, permitindo identificar vinculações legais e assegurar a aplicação dos recursos conforme sua finalidade normativa.","erradas":["As demais alternativas contrariam a definição, classificação ou consequência contábil aplicável ao caso."],"fundamento":"AFO, Direito Financeiro e Contabilidade Pública - Classificação por Fonte / Destinação de Recursos"}'::jsonb,'As normas relativas às Fontes ou Destinações de Recursos disciplinam a vinculação de determinadas receitas públicas e orientam sua adequada aplicação no orçamento. Entre essas receitas, destacam-se os royalties e as participações especiais decorrentes da exploração de recursos naturais, cuja utilização observa regras específicas. Considerando esse contexto, assinale a afirmativ') ON CONFLICT (id) DO UPDATE SET prioridade_base=EXCLUDED.prioridade_base, prioridade_faixa=EXCLUDED.prioridade_faixa, topic=EXCLUDED.topic, origin=EXCLUDED.origin, file_source=EXCLUDED.file_source, stem=EXCLUDED.stem, options=EXCLUDED.options, answer=EXCLUDED.answer, year=EXCLUDED.year, qnum=EXCLUDED.qnum, score=EXCLUDED.score, band=EXCLUDED.band, resolution=EXCLUDED.resolution, summary=EXCLUDED.summary;
INSERT INTO public.questoes (id,rank,prioridade_base,prioridade_faixa,topic,origin,file_source,stem,options,answer,year,qnum,score,band,resolution,summary) VALUES ('4108046',2291,73,'P2','AFO, Direito Financeiro e Contabilidade Pública - Classificação por Fonte / Destinação de Recursos','FSADU (UFMA) - Ass (UFMA)/UFMA/Administração/2026','Caderno Contabilidade Pública Parte 5','Consoante A Lei n° 4.320/1964, o Sumário Geral da Receita por Fontes e da Despesa por Funções integra a Lei de Orçamento. Assim, acerca das fontes e das funções de receitas e despesas orçamentárias, analise as assertivas abaixo e classifique-as em V (Verdadeira) ou F (Falsa). ( ) Entende-se como função o menor nível de agregação das diversas áreas de despesa que competem ao setor público. ( ) Denomina-se fonte de recurso a cada agrupamento de receitas que possui as mesmas normas de aplicação na despesa. ( ) A codificação para especificação das fontes ou destinação de recursos é padronizada e utilizase de dois dígitos, no intervalo de 01 a 99. ( ) O processo de vinculação entre a origem e a aplicação de recursos é instrumento de gestão da receita e da despesa ao mesmo tempo. A sequência correta é:','[["A","V – V – V – V"],["B","F – V – V – F"],["C","V – F – F – V"],["D","V – F – V – F"],["E","F – V – F – V"]]'::jsonb,'E',2026,6,NULL,NULL,'{"regra":"A resolução deve aplicar a regra orçamentária, financeira ou contábil pública pertinente ao tema, respeitando a classificação e o estágio indicados no enunciado.","passos":["Identifique o núcleo do tema: AFO, Direito Financeiro e Contabilidade Pública - Classificação por Fonte / Destinação de Recursos.","Aplique a regra ao caso concreto e elimine as alternativas incompatíveis com o conceito cobrado.","O gabarito registrado é E."],"calculo":"Quando houver valores no enunciado, a conta deve ser montada apenas com os dados fornecidos e conforme a relação conceitual indicada acima.","correta":"E — F – V – F – V","erradas":["As demais alternativas contrariam a definição, classificação ou consequência contábil aplicável ao caso."],"fundamento":"AFO, Direito Financeiro e Contabilidade Pública - Classificação por Fonte / Destinação de Recursos"}'::jsonb,'Consoante A Lei n° 4.320/1964, o Sumário Geral da Receita por Fontes e da Despesa por Funções integra a Lei de Orçamento. Assim, acerca das fontes e das funções de receitas e despesas orçamentárias, analise as assertivas abaixo e classifique-as em V (Verdadeira) ou F (Falsa). ( ) Entende-se como função o menor nível de agregação das diversas áreas de despesa que competem ao set') ON CONFLICT (id) DO UPDATE SET prioridade_base=EXCLUDED.prioridade_base, prioridade_faixa=EXCLUDED.prioridade_faixa, topic=EXCLUDED.topic, origin=EXCLUDED.origin, file_source=EXCLUDED.file_source, stem=EXCLUDED.stem, options=EXCLUDED.options, answer=EXCLUDED.answer, year=EXCLUDED.year, qnum=EXCLUDED.qnum, score=EXCLUDED.score, band=EXCLUDED.band, resolution=EXCLUDED.resolution, summary=EXCLUDED.summary;
INSERT INTO public.questoes (id,rank,prioridade_base,prioridade_faixa,topic,origin,file_source,stem,options,answer,year,qnum,score,band,resolution,summary) VALUES ('4130039',2292,73,'P2','AFO, Direito Financeiro e Contabilidade Pública - Classificação por Fonte / Destinação de Recursos','CEBRASPE (CESPE) - EGP (SEPLAG AL)/SEPLAG AL/Contabilidade/2026','Caderno Contabilidade Pública Parte 5','Julgue o item a seguir, relativos a receita pública, créditos adicionais e fonte ou destinação de recursos. A fonte ou destinação de recursos corresponde à categoria econômica da receita, razão por que sua função principal é distinguir receitas correntes de receitas de capital. Certo Errado','[]'::jsonb,'E',2026,7,NULL,NULL,'{"regra":"A resolução deve aplicar a regra orçamentária, financeira ou contábil pública pertinente ao tema, respeitando a classificação e o estágio indicados no enunciado.","passos":["Identifique o núcleo do tema: AFO, Direito Financeiro e Contabilidade Pública - Classificação por Fonte / Destinação de Recursos.","Aplique a regra ao caso concreto e elimine as alternativas incompatíveis com o conceito cobrado.","O gabarito registrado é E."],"calculo":"Quando houver valores no enunciado, a conta deve ser montada apenas com os dados fornecidos e conforme a relação conceitual indicada acima.","correta":"E — conforme o gabarito registrado no caderno.","erradas":["As demais alternativas contrariam a definição, classificação ou consequência contábil aplicável ao caso."],"fundamento":"AFO, Direito Financeiro e Contabilidade Pública - Classificação por Fonte / Destinação de Recursos"}'::jsonb,'Julgue o item a seguir, relativos a receita pública, créditos adicionais e fonte ou destinação de recursos. A fonte ou destinação de recursos corresponde à categoria econômica da receita, razão por que sua função principal é distinguir receitas correntes de receitas de capital. Certo Errado') ON CONFLICT (id) DO UPDATE SET prioridade_base=EXCLUDED.prioridade_base, prioridade_faixa=EXCLUDED.prioridade_faixa, topic=EXCLUDED.topic, origin=EXCLUDED.origin, file_source=EXCLUDED.file_source, stem=EXCLUDED.stem, options=EXCLUDED.options, answer=EXCLUDED.answer, year=EXCLUDED.year, qnum=EXCLUDED.qnum, score=EXCLUDED.score, band=EXCLUDED.band, resolution=EXCLUDED.resolution, summary=EXCLUDED.summary;
INSERT INTO public.questoes (id,rank,prioridade_base,prioridade_faixa,topic,origin,file_source,stem,options,answer,year,qnum,score,band,resolution,summary) VALUES ('4152818',2293,95,'P1','AFO, Direito Financeiro e Contabilidade Pública - Classificação da Despesa Orçamentária','IDECAN - Ana Leg (ALECE)/ALECE/Ciências Contábeis/2026','Caderno Contabilidade Pública Parte 5','O Manual de Contabilidade Aplicada ao Setor Público (MCASP) tem como objetivo auxiliar os processos de elaboração e execução orçamentária, além de reforçar o papel da contabilidade, enquanto ciência voltada ao estudo do patrimônio. Dessa forma, busca atender às necessidades informacionais dos usuários, permitindo a análise das demonstrações contábeis em conformidade com os padrões internacionais, tanto sob a perspectiva orçamentária quanto patrimonial, a partir da utilização de um Plano de Contas Nacional. Considerando a 11ª edição desse Manual, indique a afirmativa correta.','[["A","A classificação por “Função” é a que identifica a categoria econômica da despesa, dividindo-as em Despesas Correntes e Despesas de Capital."],["B","As “Inversões Financeiras” são classificadas como Despesas Correntes, pois representam dotações para a manutenção de serviços anteriormente criados."],["C","O elemento de despesa tem por finalidade identificar o objeto de gasto, sendo o primeiro dígito da codificação da natureza da despesa."],["D","A categoria econômica “Despesas de Capital” engloba, entre outras, as despesas com “Investimentos”, que visam ao planejamento e à execução de obras, inclusive a aquisição de imóveis considerados necessários à realização destas."],["E","As despesas com “Juros e Encargos da Dívida” são classificadas como Despesas de Capital, uma vez que alteram o patrimônio líquido da entidade."]]'::jsonb,'D',2026,8,NULL,NULL,'{"regra":"A resolução deve aplicar a regra orçamentária, financeira ou contábil pública pertinente ao tema, respeitando a classificação e o estágio indicados no enunciado.","passos":["Identifique o núcleo do tema: AFO, Direito Financeiro e Contabilidade Pública - Classificação da Despesa Orçamentária.","Aplique a regra ao caso concreto e elimine as alternativas incompatíveis com o conceito cobrado.","O gabarito registrado é D."],"calculo":"Quando houver valores no enunciado, a conta deve ser montada apenas com os dados fornecidos e conforme a relação conceitual indicada acima.","correta":"D — A categoria econômica “Despesas de Capital” engloba, entre outras, as despesas com “Investimentos”, que visam ao planejamento e à execução de obras, inclusive a aquisição de imóveis considerados necessários à realização destas.","erradas":["As demais alternativas contrariam a definição, classificação ou consequência contábil aplicável ao caso."],"fundamento":"AFO, Direito Financeiro e Contabilidade Pública - Classificação da Despesa Orçamentária"}'::jsonb,'O Manual de Contabilidade Aplicada ao Setor Público (MCASP) tem como objetivo auxiliar os processos de elaboração e execução orçamentária, além de reforçar o papel da contabilidade, enquanto ciência voltada ao estudo do patrimônio. Dessa forma, busca atender às necessidades informacionais dos usuários, permitindo a análise das demonstrações contábeis em conformidade com os padr') ON CONFLICT (id) DO UPDATE SET prioridade_base=EXCLUDED.prioridade_base, prioridade_faixa=EXCLUDED.prioridade_faixa, topic=EXCLUDED.topic, origin=EXCLUDED.origin, file_source=EXCLUDED.file_source, stem=EXCLUDED.stem, options=EXCLUDED.options, answer=EXCLUDED.answer, year=EXCLUDED.year, qnum=EXCLUDED.qnum, score=EXCLUDED.score, band=EXCLUDED.band, resolution=EXCLUDED.resolution, summary=EXCLUDED.summary;
INSERT INTO public.questoes (id,rank,prioridade_base,prioridade_faixa,topic,origin,file_source,stem,options,answer,year,qnum,score,band,resolution,summary) VALUES ('4152872',2294,95,'P1','AFO, Direito Financeiro e Contabilidade Pública - Classificação da Despesa Orçamentária','IDECAN - Ana Leg (ALECE)/ALECE/Ciências Contábeis/2026','Caderno Contabilidade Pública Parte 5','De acordo com a Lei nº 4.320/1964, que estatui normas gerais de direito financeiro para elaboração e controle dos orçamentos e balanços da União, dos Estados, dos Municípios e do Distrito Federal, assinale a alternativa que apresenta uma classificação correta quanto às Categorias Econômicas de Despesa.','[["A","Consideram-se Auxílios as dotações destinadas a atender a despesas de capital de entidades de direito público ou privado, com fins lucrativos, desde que autorizadas em lei especial."],["B","Classificam-se como Inversões Financeiras as dotações destinadas à aquisição de títulos representativos do capital de empresas ou entidades de qualquer espécie, já constituídas, quando a operação não importe aumento de capital."],["C","As Transferências de Capital compreendem as dotações para despesas as quais não corresponda contraprestação direta em bens ou serviços, inclusive para constituição ou aumento do capital de empresas que não sejam de caráter comercial ou financeiro."],["D","São consideradas Despesas de Custeio as dotações destinadas a obras públicas e à aquisição de instalações, equipamentos e material permanente, visando à manutenção de serviços anteriormente criados."],["E","Os Investimentos são dotações destinadas à manutenção de serviços anteriormente criados, inclusive as destinadas a atender a obras de conservação e adaptação de bens imóveis."]]'::jsonb,'B',2026,9,NULL,NULL,'{"regra":"A resolução deve aplicar a regra orçamentária, financeira ou contábil pública pertinente ao tema, respeitando a classificação e o estágio indicados no enunciado.","passos":["Identifique o núcleo do tema: AFO, Direito Financeiro e Contabilidade Pública - Classificação da Despesa Orçamentária.","Aplique a regra ao caso concreto e elimine as alternativas incompatíveis com o conceito cobrado.","O gabarito registrado é B."],"calculo":"Quando houver valores no enunciado, a conta deve ser montada apenas com os dados fornecidos e conforme a relação conceitual indicada acima.","correta":"B — Classificam-se como Inversões Financeiras as dotações destinadas à aquisição de títulos representativos do capital de empresas ou entidades de qualquer espécie, já constituídas, quando a operação não importe aumento de capital.","erradas":["As demais alternativas contrariam a definição, classificação ou consequência contábil aplicável ao caso."],"fundamento":"AFO, Direito Financeiro e Contabilidade Pública - Classificação da Despesa Orçamentária"}'::jsonb,'De acordo com a Lei nº 4.320/1964, que estatui normas gerais de direito financeiro para elaboração e controle dos orçamentos e balanços da União, dos Estados, dos Municípios e do Distrito Federal, assinale a alternativa que apresenta uma classificação correta quanto às Categorias Econômicas de Despesa.') ON CONFLICT (id) DO UPDATE SET prioridade_base=EXCLUDED.prioridade_base, prioridade_faixa=EXCLUDED.prioridade_faixa, topic=EXCLUDED.topic, origin=EXCLUDED.origin, file_source=EXCLUDED.file_source, stem=EXCLUDED.stem, options=EXCLUDED.options, answer=EXCLUDED.answer, year=EXCLUDED.year, qnum=EXCLUDED.qnum, score=EXCLUDED.score, band=EXCLUDED.band, resolution=EXCLUDED.resolution, summary=EXCLUDED.summary;
INSERT INTO public.questoes (id,rank,prioridade_base,prioridade_faixa,topic,origin,file_source,stem,options,answer,year,qnum,score,band,resolution,summary) VALUES ('4213060',2295,95,'P1','AFO, Direito Financeiro e Contabilidade Pública - Classificação da Despesa Orçamentária','VUNESP - ACI (Pref Jardinópolis)/Pref Jardinópolis/2026','Caderno Contabilidade Pública Parte 5','De acordo com a classificação da despesa pública prevista na Lei nº 4.320, de 1964, assinale a alternativa em que todas as despesas apresentadas são classificadas como inversões financeiras.','[["A","Construção de escola pública; aquisição de equipamento hospitalar; pavimentação de rodovia."],["B","Aquisição de imóvel já em uso; concessão de empréstimo a empresa estatal; aquisição de ações de empresa privada."],["C","Repasse de recursos para construção de hospital; concessão de subvenção social; pagamento de serviços terceirizados."],["D","Aquisição de equipamentos permanentes; reforma de prédio público; construção de unidade administrativa."],["E","Concessão de empréstimo a município; repasse de recursos para custeio de entidade privada; aquisição de material de consumo."]]'::jsonb,'B',2026,10,NULL,NULL,'{"regra":"A resolução deve aplicar a regra orçamentária, financeira ou contábil pública pertinente ao tema, respeitando a classificação e o estágio indicados no enunciado.","passos":["Identifique o núcleo do tema: AFO, Direito Financeiro e Contabilidade Pública - Classificação da Despesa Orçamentária.","Aplique a regra ao caso concreto e elimine as alternativas incompatíveis com o conceito cobrado.","O gabarito registrado é B."],"calculo":"Quando houver valores no enunciado, a conta deve ser montada apenas com os dados fornecidos e conforme a relação conceitual indicada acima.","correta":"B — Aquisição de imóvel já em uso; concessão de empréstimo a empresa estatal; aquisição de ações de empresa privada.","erradas":["As demais alternativas contrariam a definição, classificação ou consequência contábil aplicável ao caso."],"fundamento":"AFO, Direito Financeiro e Contabilidade Pública - Classificação da Despesa Orçamentária"}'::jsonb,'De acordo com a classificação da despesa pública prevista na Lei nº 4.320, de 1964, assinale a alternativa em que todas as despesas apresentadas são classificadas como inversões financeiras.') ON CONFLICT (id) DO UPDATE SET prioridade_base=EXCLUDED.prioridade_base, prioridade_faixa=EXCLUDED.prioridade_faixa, topic=EXCLUDED.topic, origin=EXCLUDED.origin, file_source=EXCLUDED.file_source, stem=EXCLUDED.stem, options=EXCLUDED.options, answer=EXCLUDED.answer, year=EXCLUDED.year, qnum=EXCLUDED.qnum, score=EXCLUDED.score, band=EXCLUDED.band, resolution=EXCLUDED.resolution, summary=EXCLUDED.summary;
INSERT INTO public.questoes (id,rank,prioridade_base,prioridade_faixa,topic,origin,file_source,stem,options,answer,year,qnum,score,band,resolution,summary) VALUES ('4222091',2296,95,'P1','AFO, Direito Financeiro e Contabilidade Pública - Classificação da Despesa Orçamentária','FEPESE - Tec Con (Pref Itajaí)/Pref Itajaí/2026','Caderno Contabilidade Pública Parte 5','Quanto à classificação por categoria econômica, as despesas classificam-se em:','[["A","Ordinárias e extraordinárias permanentes."],["B","Receitas primárias e receitas financeiras."],["C","Operações patrimoniais e compensatórias."],["D","Despesas correntes e despesas de capital."],["E","Administrativas e finalísticas."]]'::jsonb,'D',2026,11,NULL,NULL,'{"regra":"A resolução deve aplicar a regra orçamentária, financeira ou contábil pública pertinente ao tema, respeitando a classificação e o estágio indicados no enunciado.","passos":["Identifique o núcleo do tema: AFO, Direito Financeiro e Contabilidade Pública - Classificação da Despesa Orçamentária.","Aplique a regra ao caso concreto e elimine as alternativas incompatíveis com o conceito cobrado.","O gabarito registrado é D."],"calculo":"Quando houver valores no enunciado, a conta deve ser montada apenas com os dados fornecidos e conforme a relação conceitual indicada acima.","correta":"D — Despesas correntes e despesas de capital.","erradas":["As demais alternativas contrariam a definição, classificação ou consequência contábil aplicável ao caso."],"fundamento":"AFO, Direito Financeiro e Contabilidade Pública - Classificação da Despesa Orçamentária"}'::jsonb,'Quanto à classificação por categoria econômica, as despesas classificam-se em:') ON CONFLICT (id) DO UPDATE SET prioridade_base=EXCLUDED.prioridade_base, prioridade_faixa=EXCLUDED.prioridade_faixa, topic=EXCLUDED.topic, origin=EXCLUDED.origin, file_source=EXCLUDED.file_source, stem=EXCLUDED.stem, options=EXCLUDED.options, answer=EXCLUDED.answer, year=EXCLUDED.year, qnum=EXCLUDED.qnum, score=EXCLUDED.