INSERT INTO public.questoes (id,rank,prioridade_base,prioridade_faixa,topic,origin,file_source,stem,options,answer,year,qnum,score,band,resolution,summary) VALUES ('4195368',2297,95,'P1','AFO, Direito Financeiro e Contabilidade Pública - Estágios da Despesa Pública','FGV - ACE (TCE-PE)/TCE PE/Contas Públicas/2026','Caderno Contabilidade Pública Parte 5','Uma entidade do setor público realizou um empenho estimativo para a despesa com o serviço de fornecimento de energia elétrica no exercício de 2025. Ao final do exercício, verificou-se que o valor empenhado excedeu o montante efetivamente realizado da despesa. Nesse caso, é correto afirmar que o','[["A","empenho será anulado parcialmente."],["B","empenho será anulado integralmente."],["C","montante reconhecido como despesa será aumentado."],["D","valor excedente será direcionado para despesa de natureza semelhante."],["E","valor excedente irá constituir conta de reserva, para ser utilizado no exercício seguinte."]]'::jsonb,'A',2026,12,NULL,NULL,'{"regra":"A resolução deve aplicar a regra orçamentária, financeira ou contábil pública pertinente ao tema, respeitando a classificação e o estágio indicados no enunciado.","passos":["Identifique o núcleo do tema: AFO, Direito Financeiro e Contabilidade Pública - Estágios da Despesa Pública.","Aplique a regra ao caso concreto e elimine as alternativas incompatíveis com o conceito cobrado.","O gabarito registrado é A."],"calculo":"Quando houver valores no enunciado, a conta deve ser montada apenas com os dados fornecidos e conforme a relação conceitual indicada acima.","correta":"A — empenho será anulado parcialmente.","erradas":["As demais alternativas contrariam a definição, classificação ou consequência contábil aplicável ao caso."],"fundamento":"AFO, Direito Financeiro e Contabilidade Pública - Estágios da Despesa Pública"}'::jsonb,'Uma entidade do setor público realizou um empenho estimativo para a despesa com o serviço de fornecimento de energia elétrica no exercício de 2025. Ao final do exercício, verificou-se que o valor empenhado excedeu o montante efetivamente realizado da despesa. Nesse caso, é correto afirmar que o') ON CONFLICT (id) DO UPDATE SET prioridade_base=EXCLUDED.prioridade_base, prioridade_faixa=EXCLUDED.prioridade_faixa, topic=EXCLUDED.topic, origin=EXCLUDED.origin, file_source=EXCLUDED.file_source, stem=EXCLUDED.stem, options=EXCLUDED.options, answer=EXCLUDED.answer, year=EXCLUDED.year, qnum=EXCLUDED.qnum, score=EXCLUDED.score, band=EXCLUDED.band, resolution=EXCLUDED.resolution, summary=EXCLUDED.summary;
INSERT INTO public.questoes (id,rank,prioridade_base,prioridade_faixa,topic,origin,file_source,stem,options,answer,year,qnum,score,band,resolution,summary) VALUES ('4216144',2298,95,'P1','AFO, Direito Financeiro e Contabilidade Pública - Estágios da Despesa Pública','Instituto Verbena - FTrib (Pref Buriti Alegre)/Pref Buriti Alegre/2026','Caderno Contabilidade Pública Parte 5','Durante a execução de uma despesa pública, antes da entrega do bem e da verificação do direito do credor, a autoridade competente pratica o ato que vincula dotação orçamentária ao atendimento da obrigação assumida pela Administração. Esse ato corresponde ao(à)','[["A","pagamento."],["B","liquidação."],["C","empenho."],["D","lançamento."]]'::jsonb,'C',2026,13,NULL,NULL,'{"regra":"A resolução deve aplicar a regra orçamentária, financeira ou contábil pública pertinente ao tema, respeitando a classificação e o estágio indicados no enunciado.","passos":["Identifique o núcleo do tema: AFO, Direito Financeiro e Contabilidade Pública - Estágios da Despesa Pública.","Aplique a regra ao caso concreto e elimine as alternativas incompatíveis com o conceito cobrado.","O gabarito registrado é C."],"calculo":"Quando houver valores no enunciado, a conta deve ser montada apenas com os dados fornecidos e conforme a relação conceitual indicada acima.","correta":"C — empenho.","erradas":["As demais alternativas contrariam a definição, classificação ou consequência contábil aplicável ao caso."],"fundamento":"AFO, Direito Financeiro e Contabilidade Pública - Estágios da Despesa Pública"}'::jsonb,'Durante a execução de uma despesa pública, antes da entrega do bem e da verificação do direito do credor, a autoridade competente pratica o ato que vincula dotação orçamentária ao atendimento da obrigação assumida pela Administração. Esse ato corresponde ao(à)') ON CONFLICT (id) DO UPDATE SET prioridade_base=EXCLUDED.prioridade_base, prioridade_faixa=EXCLUDED.prioridade_faixa, topic=EXCLUDED.topic, origin=EXCLUDED.origin,