INSERT INTO public.questoes (id,rank,prioridade_base,prioridade_faixa,topic,origin,file_source,stem,options,answer,year,qnum,score,band,resolution,summary) VALUES ('4222090',2299,95,'P1','AFO, Direito Financeiro e Contabilidade Pública - Estágios da Despesa Pública','FEPESE - Tec Con (Pref Itajaí)/Pref Itajaí/2026','Caderno Contabilidade Pública Parte 5','O estágio da despesa pública em que consiste na verificação do direito adquirido pelo credor tendo por base os títulos e documentos comprobatórios do respectivo crédito, denomina-se:','[["A","Liquidação da despesa pública."],["B","Fixação da despesa orçamentária."],["C","Empenho da despesa pública."],["D","Programação financeira anual."],["E","Arrecadação da receita pública."]]'::jsonb,'A',2026,14,NULL,NULL,'{"regra":"A resolução deve aplicar a regra orçamentária, financeira ou contábil pública pertinente ao tema, respeitando a classificação e o estágio indicados no enunciado.","passos":["Identifique o núcleo do tema: AFO, Direito Financeiro e Contabilidade Pública - Estágios da Despesa Pública.","Aplique a regra ao caso concreto e elimine as alternativas incompatíveis com o conceito cobrado.","O gabarito registrado é A."],"calculo":"Quando houver valores no enunciado, a conta deve ser montada apenas com os dados fornecidos e conforme a relação conceitual indicada acima.","correta":"A — Liquidação da despesa pública.","erradas":["As demais alternativas contrariam a definição, classificação ou consequência contábil aplicável ao caso."],"fundamento":"AFO, Direito Financeiro e Contabilidade Pública - Estágios da Despesa Pública"}'::jsonb,'O estágio da despesa pública em que consiste na verificação do direito adquirido pelo credor tendo por base os títulos e documentos comprobatórios do respectivo crédito, denomina-se:') ON CONFLICT (id) DO UPDATE SET prioridade_base=EXCLUDED.prioridade_base, prioridade_faixa=EXCLUDED.prioridade_faixa, topic=EXCLUDED.topic, origin=EXCLUDED.origin, file_source=EXCLUDED.file_source, stem