INSERT INTO public.questoes (id,rank,prioridade_base,prioridade_faixa,topic,origin,file_source,stem,options,answer,year,qnum,score,band,resolution,summary) VALUES ('4222111',2300,95,'P1','AFO, Direito Financeiro e Contabilidade Pública - Estágios da Despesa Pública','FEPESE - Tec Con (Pref Itajaí)/Pref Itajaí/2026','Caderno Contabilidade Pública Parte 5','De acordo com o Manual de Contabilidade Aplicada ao Setor Público (MCASP – 11ª edição), os estágios da execução da despesa orçamentária são:','[["A","Empenho, liquidação e pagamento."],["B","Fixação, empenho, liquidação e pagamento."],["C","Lançamento, previsão, liquidação e recolhimento."],["D","Arrecadação, previsão, empenho e pagamento."],["E","Fixação, recolhimento, arrecadação e liquidação."]]'::jsonb,'A',2026,15,NULL,NULL,'{"regra":"A resolução deve aplicar a regra orçamentária, financeira ou contábil pública pertinente ao tema, respeitando a classificação e o estágio indicados no enunciado.","passos":["Identifique o núcleo do tema: AFO, Direito Financeiro e Contabilidade Pública - Estágios da Despesa Pública.","Aplique a regra ao caso concreto e elimine as alternativas incompatíveis com o conceito cobrado.","O gabarito registrado é A."],"calculo":"Quando houver valores no enunciado, a conta deve ser montada apenas com os dados fornecidos e conforme a relação conceitual indicada acima.","correta":"A — Empenho, liquidação e pagamento.","erradas":["As demais alternativas contrariam a definição, classificação ou consequência contábil aplicável ao caso."],"fundamento":"AFO, Direito Financeiro e Contabilidade Pública - Estágios da Despesa Pública"}'::jsonb,'De acordo com o Manual de Contabilidade Aplicada ao Setor Público (MCASP – 11ª edição), os estágios da execução da despesa orçamentária são:') ON CONFLICT (id) DO UPDATE SET prioridade_base=EXCLUDED.prioridade_base, prioridade_faixa=EXCLUDED.prioridade_faixa, topic=EXCLUDED.topic, origin=EXCLUDED.origin, file_source=EXCLUDED.file_source, stem=EXCLUDED.stem, options=EXCLUDED.options, answer=EXCLUDED.answer, year=EXCLUDED.year, qnum=EXCLUDED.qnum, score=EXCLUDED.score, band=EXCLUDED.band, resolution=EXCLUDED.resolution, summary=EXCLUDED.summary;
INSERT INTO public.questoes (id,rank,prioridade_base,prioridade_faixa,topic,origin,file_source,stem,options,answer,year,qnum,score,band,resolution,summary) VALUES ('4002750',2301,93,'P1','AFO, Direito Financeiro e Contabilidade Pública - SICONFI - Sistema de Informações Contábeis e Fiscais do Setor Público Brasileiro','AVANÇASP - Cont (Pref Taiúva)/Pref Taiúva/2026','Caderno Contabilidade Pública Parte 5','No contexto da transparência e da padronização das informações fiscais no setor público, foi instituído um sistema chamado SICONFI, que tem a finalidade de centralizar o envio e promover a análise de dados dos entes federativos. Sinalize a alternativa correta acerca desse sistema:','[["A","Destina-se exclusivamente ao registro de operações bancárias dos entes públicos, principalmente os privados."],["B","É utilizado apenas para controle interno, sem relação com normas fiscais."],["C","É uma ferramenta destinada ao recebimento e análise de informações contábeis, financeiras e orçamentárias, abrangendo relatórios previstos na Lei de Responsabilidade Fiscal."],["D","Substitui integralmente a contabilidade dos entes públicos."],["E","É utilizado apenas para elaboração de folhas de pagamento."]]'::jsonb,'C',2026,16,NULL,NULL,'{"regra":"A resolução deve aplicar a regra orçamentária, financeira ou contábil pública pertinente ao tema, respeitando a classificação e o estágio indicados no enunciado.","passos":["Identifique o núcleo do tema: AFO, Direito Financeiro e Contabilidade Pública - SICONFI - Sistema de Informações Contábeis e Fiscais do Setor Público Brasileiro.","Aplique a regra ao caso concreto e elimine as alternativas incompatíveis com o conceito cobrado.","O gabarito registrado é C."],"calculo":"Quando houver valores no enunciado, a conta deve ser montada apenas com os dados fornecidos e conforme a relação conceitual indicada acima.","correta":"C — É uma ferramenta destinada ao recebimento e análise de informações contábeis, financeiras e orçamentárias, abrangendo relatórios previstos na Lei de Responsabilidade Fiscal.","erradas":["As demais alternativas contrariam a definição, classificação ou consequência contábil aplicável ao caso."],"fundamento":"AFO, Direito Financeiro e Contabilidade Pública - SICONFI - Sistema de Informações Contábeis e Fiscais do Setor Público Brasileiro"}'::jsonb,'No contexto da transparência e da padronização das informações fiscais no setor público, foi instituído um sistema chamado SICONFI, que tem a finalidade de centralizar o envio e promover a análise de dados dos entes federativos. Sinalize a alternativa correta acerca desse sistema:') ON CONFLICT (id) DO UPDATE SET prioridade_base=EXCLUDED.prioridade_base, prioridade_faixa=EXCLUDED.prioridade_faixa, topic=EXCLUDED.topic, origin=EXCLUDED.origin, file_source=EXCLUDED.file_source, stem=EXCLUDED.stem, options=EXCLUDED.options, answer=EXCLUDED.answer, year=EXCLUDED.year, qnum=EXCLUDED.qnum, score=EXCLUDED.score, band=EXCLUDED.band, resolution=EXCLUDED.resolution, summary=EXCLUDED.summary;
INSERT INTO public.questoes (id,rank,prioridade_base,prioridade_faixa,topic,origin,file_source,stem,options,answer,year,qnum,score,band,resolution,summary) VALUES ('4003970',2302,93,'P1','AFO, Direito Financeiro e Contabilidade Pública - SICONFI - Sistema de Informações Contábeis e Fiscais do Setor Público Brasileiro','Legalle - GAPE (FJP)/FJP/Nível II/Contabilidade/2026','Caderno Contabilidade Pública Parte 5','O Sistema de Informações Contábeis e Fiscais do Setor Público Brasileiro (SICONFI) é um sistema desenvolvido pelo Tesouro Nacional em parceria com o Serviço Federal de Processamento de Dados (SERPRO), cujo objetivo é se tornar o mais importante canal de intercâmbio de informações fiscais, contábeis e financeiras entre a União e os demais entes da Federação. À luz de suas finalidades institucionais, assinale a alternativa que NÃO corresponde a um dos objetivos do SICONFI.','[["A","Melhorar a qualidade das informações produzidas pelo setor público."],["B","Atuar como ferramenta de recepção de dados e informações fiscais dos entes federativos."],["C","Aperfeiçoar os mecanismos de obtenção, sistematização e divulgação de dados fiscais."],["D","Funcionar como sistema de registro contábil e de execução orçamentária dos entes públicos."]]'::jsonb,'D',2026,17,NULL,NULL,'{"regra":"A resolução deve aplicar a regra orçamentária, financeira ou contábil pública pertinente ao tema, respeitando a classificação e o estágio indicados no enunciado.","passos":["Identifique o núcleo do tema: AFO, Direito Financeiro e Contabilidade Pública - SICONFI - Sistema de Informações Contábeis e Fiscais do Setor Público Brasileiro.","Aplique a regra ao caso concreto e elimine as alternativas incompatíveis com o conceito cobrado.","O gabarito registrado é D."],"calculo":"Quando houver valores no enunciado, a conta deve ser montada apenas com os dados fornecidos e conforme a relação conceitual indicada acima.","correta":"D — Funcionar como sistema de registro contábil e de execução orçamentária dos entes públicos.","erradas":["As demais alternativas contrariam a definição, classificação ou consequência contábil aplicável ao caso."],"fundamento":"AFO, Direito Financeiro e Contabilidade Pública - SICONFI - Sistema de Informações Contábeis e Fiscais do Setor Público Brasileiro"}'::jsonb,'O Sistema de Informações Contábeis e Fiscais do Setor Público Brasileiro (SICONFI) é um sistema desenvolvido pelo Tesouro Nacional em parceria com o Serviço Federal de Processamento de Dados (SERPRO), cujo objetivo é se tornar o mais importante canal de intercâmbio de informações fiscais, contábeis e financeiras entre a União e os demais entes da Federação. À luz de suas finali') ON CONFLICT (id) DO UPDATE SET prioridade_base=EXCLUDED.prioridade_base, prioridade_faixa=EXCLUDED.prioridade_faixa, topic=EXCLUDED.topic, origin=EXCLUDED.origin, file_source=EXCLUDED.file_source, stem=EXCLUDED.stem, options=EXCLUDED.options, answer=EXCLUDED.answer, year=EXCLUDED.year, qnum=EXCLUDED.qnum, score=EXCLUDED.score, band=EXCLUDED.band, resolution=EXCLUDED.resolution, summary=EXCLUDED.summary;
INSERT INTO public.questoes (id,rank,prioridade_base,prioridade_faixa,topic,origin,file_source,stem,options,answer,year,qnum,score,band,resolution,summary) VALUES ('4089431',2303,83,'P1','AFO, Direito Financeiro e Contabilidade Pública - Bases de Mensuração de Ativos e Passivos (MCASP e NBC TSP EC)','IBADE - Cont (COREN AM)/COREN AM/2026','Caderno Contabilidade Pública Parte 5','As Normas Brasileiras de Contabilidade Aplicadas ao Setor Público (NBC TSP) admitem diferentes bases de mensuração, conforme a natureza do elemento contábil, incluindo, EXCETO:','[["A","valor recuperável."],["B","custo de reposição."],["C","valor em uso."],["D","valor utilizável bruto."],["E","valor justo."]]'::jsonb,'D',2026,18,NULL,NULL,'{"regra":"A resolução deve aplicar a regra orçamentária, financeira ou contábil pública pertinente ao tema, respeitando a classificação e o estágio indicados no enunciado.","passos":["Identifique o núcleo do tema: AFO, Direito Financeiro e Contabilidade Pública - Bases de Mensuração de Ativos e Passivos (MCASP e NBC TSP EC).","Aplique a regra ao caso concreto e elimine as alternativas incompatíveis com o conceito cobrado.","O gabarito registrado é D."],"calculo":"Quando houver valores no enunciado, a conta deve ser montada apenas com os dados fornecidos e conforme a relação conceitual indicada acima.","correta":"D — valor utilizável bruto.","erradas":["As demais alternativas contrariam a definição, classificação ou consequência contábil aplicável ao caso."],"fundamento":"AFO, Direito Financeiro e Contabilidade Pública - Bases de Mensuração de Ativos e Passivos (MCASP e NBC TSP EC)"}'::jsonb,'As Normas Brasileiras de Contabilidade Aplicadas ao Setor Público (NBC TSP) admitem diferentes bases de mensuração, conforme a natureza do elemento contábil, incluindo, EXCETO:') ON CONFLICT (id) DO UPDATE SET prioridade_base=EXCLUDED.prioridade_base, prioridade_faixa=EXCLUDED.prioridade_faixa, topic=EXCLUDED.topic, origin=EXCLUDED.origin, file_source=EXCLUDED.file_sou