INSERT INTO public.questoes (id,rank,prioridade_base,prioridade_faixa,topic,origin,file_source,stem,options,answer,year,qnum,score,band,resolution,summary) VALUES ('4130068',2304,83,'P1','AFO, Direito Financeiro e Contabilidade Pública - Bases de Mensuração de Ativos e Passivos (MCASP e NBC TSP EC)','CEBRASPE (CESPE) - EGP (SEPLAG AL)/SEPLAG AL/Contabilidade/2026','Caderno Contabilidade Pública Parte 5','No que se refere a provisões, estoques e créditos adicionais de ente público, julgue o item. Considere que uma entidade pública mantenha estoques destinados à distribuição gratuita, cujo custo registrado seja de R$ 150.000. Considere, ainda, que o custo corrente de reposição desses estoques seja de R$ 120.000 e que o valor realizável líquido seja de R$ 130.000. Nessa situação hipotética, os estoques devem ser mensurados, de acordo com a NBC TSP 04, por R$ 120.000 Certo Errado','[]'::jsonb,'C',2026,19,NULL,NULL,'{"regra":"A resolução deve aplicar a regra orçamentária, financeira ou contábil pública pertinente ao tema, respeitando a classificação e o estágio indicados no enunciado.","passos":["Identifique o núcleo do tema: AFO, Direito Financeiro e Contabilidade Pública - Bases de Mensuração de Ativos e Passivos (MCASP e NBC TSP EC).","Aplique a regra ao caso concreto e elimine as alternativas incompatíveis com o conceito cobrado.","O gabarito registrado é C."],"calculo":"Quando houver valores no enunciado, a conta deve ser montada apenas com os dados fornecidos e conforme a relação conceitual indicada acima.","correta":"C — conforme o gabarito registrado no caderno.","erradas":["As demais alternativas contrariam a definição, classificação ou consequência contábil aplicável ao caso."],"fundamento":"AFO, Direito Financeiro e Contabilidade Pública - Bases de Mensuração de Ativos e Passivos (MCASP e NBC TSP EC)"}'::jsonb,'No que se refere a provisões, estoques e créditos adicionais de ente público, julgue o item. Considere que uma entidade pública mantenha estoques destinados à distribuição gratuita, cujo custo registrado seja de R$ 150.000. Considere, ainda, que o custo corrente de reposição desses estoques seja de R$ 120.000 e que o valor realizável líquido seja de R$ 130.000. Nessa situação h') ON CONFLICT (id) DO UPDATE SET prioridade_base=EXCLUDED.prioridade_base, prioridade_faixa=EXCLUDED.prioridade_faixa, topic=EXCLUDED.topic, origin=EXCLUDED.origin, file_source=EXCLUDED.file_source, stem=EXCLUDED.stem, options=EXCLUDED.options, answer=EXCLUDED.answer, year=EXCLUDED.year, qnum=EXCLUDED.qnum, score=EXCLUDED.score, band=EXCLUDED.band, resolution=EXCLUDED.resolution, summary=EXCLUDED.summary;
INSERT INTO public.questoes (id,rank,prioridade_base,prioridade_faixa,topic,origin,file_source,stem,options,answer,year,qnum,score,band,resolution,summary) VALUES ('4193771',2305,97,'P1','AFO, Direito Financeiro e Contabilidade Pública - Plano de Contas (PCASP)','CEBRASPE (CESPE) - ACI (CGE AL)/CGE AL/2026','Caderno Contabilidade Pública Parte 5','Ao realizar a conformidade contábil nos registros de determinada secretaria de Estado, um analista de controle interno da CGE deve analisar se os lançamentos respeitam a estrutura de classes do PCASP e os atributos da informação contábil, bem como se as naturezas de informação (orçamentária, patrimonial e de controle) estão integradas e suas autonomias, preservadas, conforme as regras do setor público. Com base no exposto, julgue o item subsequente. As contas da natureza de informação de controle, representadas pelas classes 7 e 8, registram, processam e evidenciam os atos e os fatos relacionados ao planejamento e à execução orçamentária. Certo Errado','[]'::jsonb,'E',2026,20,NULL,NULL,'{"regra":"A resolução deve aplicar a regra orçamentária, financeira ou contábil pública pertinente ao tema, respeitando a classificação e o estágio indicados no enunciado.","passos":["Identifique o núcleo do tema: AFO, Direito Financeiro e Contabilidade Pública - Plano de Contas (PCASP).","Aplique a regra ao caso concreto e elimine as alternativas incompatíveis com o conceito cobrado.","O gabarito registrado é E."],"calculo":"Quando houver valores no enunciado, a conta deve ser montada apenas com os dados fornecidos e conforme a relação conceitual indicada acima.","correta":"E — conforme o gabarito registrado no caderno.","erradas":["As demais alternativas contrariam a definição, classificação ou consequência contábil aplicável ao caso."],"fundamento":"AFO, Direito Financeiro e Contabilidade Pública - Plano de Contas (PCASP)"}'::jsonb,'Ao realizar a conformidade contábil nos registros de determinada secretaria de Estado, um analista de controle interno da CGE deve analisar se os lançamentos respeitam a estrutura de classes do PCASP e os atributos da informação contábil, bem como se as naturezas de informação (orçamentária, patrimonial e de controle) estão integradas e suas autonomias, preservadas, conforme as') ON CONFLICT (id) DO UPDATE SET prioridade_base=EXCLUDED.prioridade_base, prioridade_faixa=EXCLUDED.prioridade_faixa, topic=EXCLUDED.topic, origin=EXCLUDED.origin, file_source=EXCLUDED.file_source, stem=EXCLUDED.stem, options=EXCLUDED.options, answer=EXCLUDED.answer, year=EXCLUDED.year, qnum=EXCLUDED.qnum, score=EXCLUDED.score, band=EXCLUDED.band, resolution=EXCLUDED.resolution, summary=EXCLUDED.summary;
INSERT INTO public.questoes (id,rank,prioridade_base,prioridade_faixa,topic,origin,file_source,stem,options,answer,year,qnum,score,band,resolution,summary) VALUES ('4193774',2306,97,'P1','AFO, Direito Financeiro e Contabilidade Pública - Plano de Contas (PCASP)','CEBRASPE (CESPE) - ACI (CGE AL)/CGE AL/2026','Caderno Contabilidade Pública Parte 5','Ao realizar a conformidade contábil nos registros de determinada secretaria de Estado, um analista de controle interno da CGE deve analisar se os lançamentos respeitam a estrutura de classes do PCASP e os atributos da informação contábil, bem como se as naturezas de informação (orçamentária, patrimonial e de controle) estão integradas e suas autonomias, preservadas, conforme as regras do setor público. Com base no exposto, julgue o item subsequente. Consoante as regras de integridade do PCASP, os lançamentos contábeis devem ser feitos por meio de partidas dobradas de acordo com a mesma natureza de informação, de modo que um registro na classe 1 (ativo) tenha sempre uma contrapartida nas classes 1, 2, 3 ou 4. Certo Errado','[]'::jsonb,'C',2026,21,NULL,NULL,'{"regra":"A resolução deve aplicar a regra orçamentária, financeira ou contábil pública pertinente ao tema, respeitando a classificação e o estágio indicados no enunciado.","passos":["Identifique o núcleo do tema: AFO, Direito Financeiro e Contabilidade Pública - Plano de Contas (PCASP).","Aplique a regra ao caso concreto e elimine as alternativas incompatíveis com o conceito cobrado.","O gabarito registrado é C."],"calculo":"Quando houver valores no enunciado, a conta deve ser montada apenas com os dados fornecidos e conforme a relação conceitual indicada acima.","correta":"C — conforme o gabarito registrado no caderno.","erradas":["As demais alternativas contrariam a definição, classificação ou consequência contábil aplicável ao caso."],"fundamento":"AFO, Direito Financeiro e Contabilidade Pública - Plano de Contas (PCASP)"}'::jsonb,'Ao realizar a conformidade contábil nos registros de determinada secretaria de Estado, um analista de controle interno da CGE deve analisar se os lançamentos respeitam a estrutura de classes do PCASP e os atributos da informação contábil, bem como se as naturezas de informação (orçamentária, patrimonial e de controle) estão integradas e suas autonomias, preservadas, conforme as') ON CONFLICT (id) DO UPDATE SET prioridade_base=EXCLUDED.prioridade_base, prioridade_faixa=EXCLUDED.prioridade_faixa, topic=EXCLUDED.topic, origin=EXCLUDED.origin, file_source=EXCLUDED.file_source, stem=EXCLUDED.stem, options=EXCLUDED.options, answer=EXCLUDED.answer, year=EXCLUDED.year, qnum=EXCLUDED.qnum, score=EXCLUDED.score, band=EXCLUDED.band, resolution=EXCLUDED.resolution, summary=EXCLUDED.summary;
INSERT INTO public.questoes (id,rank,prioridade_base,prioridade_faixa,topic,origin,file_source,stem,options,answer,year,qnum,score,band,resolution,summary) VALUES ('4197630',2307,97,'P1','AFO, Direito Financeiro e Contabilidade Pública - Plano de Contas (PCASP)','FGV - AUCE (TCE-PE)/TCE PE/Contas Públicas/2026','Caderno Contabilidade Pública Parte 5','Ao avaliar o Plano de Contas Aplicado ao Setor Público (PCASP) de uma entidade do setor público, um auditor verificou o registro da inscrição de restos a pagar. Esse registro é apresentado na seguinte classe:','[["A","Controles Devedores, sendo de natureza de controle."],["B","Variação Patrimonial Diminutiva, sendo de natureza patrimonial."],["C","Variação Patrimonial Aumentativa, sendo de natureza patrimonial."],["D","Controles da Execução do Planejamento e Orçamento, sendo de natureza orçamentária."],["E","Controles da Aprovação do Planejamento e Orçamento, sendo de natureza orçamentária."]]'::jsonb,'E',2026,22,NULL,NULL,'{"regra":"A resolução deve aplicar a regra orçamentária, financeira ou contábil pública pertinente ao tema, respeitando a classificação e o estágio indicados no enunciado.","passos":["Identifique o núcleo do tema: AFO, Direito Financeiro e Contabilidade Pública - Plano de Contas (PCASP).","Aplique a regra ao caso concreto e elimine as alternativas incompatíveis com o conceito cobrado.","O gabarito registrado é E."],"calculo":"Quando houver valores no enunciado, a conta deve ser montada apenas com os dados fornecidos e conforme a relação conceitual indicada acima.","correta":"E — Controles da Aprovação do Planejamento e Orçamento, sendo de natureza orçamentária.","erradas":["As demais alternativas contrariam a definição, classificação ou consequência contábil aplicável ao caso."],"fundamento":"AFO, Direito Financeiro e Contabilidade Pública - Plano de Contas (PCASP)"}'::jsonb,'Ao avaliar o Plano de Contas Aplicado ao Setor Público (PCASP) de uma entidade do setor público, um auditor verificou o registro da inscrição de restos a pagar. Esse registro é apresentado na seguinte classe:') ON CONFLICT (id) DO UPDATE SET prioridade_base=EXCLUDED.prioridade_base, prioridade_faixa=EXCLUDED.prioridade_faixa, topic=EXCLUDED.topic, origin=EXCLUDED.origin, file_source=EXCLUDED.file_source, stem=EXCLUDED.stem, options=EXCLUDED.options, answer=EXCLUDED.answer, year=EXCLUDED.year, qnum=EXCLUDED.qnum, score=EXCLUDED.score, band=EXCLUDED.band, resolution=EXCLUDED.resolution, summary=EXCLUDED.summary;
